(function(){
'use strict';
const D=globalThis.RA.D;
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('stipulate','Stipulate comes from Latin stipulari, “to bargain or make a formal promise”; English uses it for stating a condition as part of an agreement.',[C('stipulate.s1','contracts','The lease stipulates that tenants must give thirty days’ notice before leaving.','租约规定，租户搬离前必须提前三十天通知。','stipulate that; stipulate a condition in a contract','及物动词表示把某项要求或条件明确列入协议。','The lease makes notice a stated requirement.','租约把通知期列为明确要求。')],M('The lease stipulates thirty days’ notice, but the tenant can leave without notice under the same clause.','The lease stipulates thirty days’ notice, so the tenant must notify the landlord before leaving.','stipulate 表示正式规定条件；允许不通知与条款相反。','meaning'),[Q(1,'What does the lease require?','thirty days’ notice before leaving','a stocklist before moving','a new kitchen stove','Stipulate means state a condition formally.'),Q(1,'Where is the requirement stated?','in the lease','on a strawberry label','in a medical chart','The context says the lease includes the condition.'),Q(1,'Which pattern follows stipulate?','stipulate that tenants must give notice','stipulate tenants to giving notice','stipulate for tenants notice that','The verb commonly takes a that-clause for a requirement.','grammar'),Q(1,'What does stipulate mean here?','make a requirement part of an agreement','estimate a building’s height','stop working suddenly','The lease formally states the condition.')]);
P('stipulation','Stipulation is formed from stipulate + -ion; it names a particular requirement written into a contract, settlement, or agreement.',C('stipulation.s1','contracts','One stipulation of the settlement is that the company remove the damaged sign by Friday.','和解协议的一项条款是公司必须在周五前拆除受损标牌。','a stipulation of/in an agreement; meet a stipulation','名词指协议中写明的一项具体要求。','The removal deadline appears as a condition of settlement.','拆除期限是和解协议中的条件。'),M('The settlement’s stipulation required the sign to stay, but the company removed it before the agreed date.','The settlement’s stipulation required the company to remove the sign by Friday.','提前拆除不违反“周五前拆除”的要求；原句错误地说必须保留。','meaning'),[Q(1,'What is one stipulation in the settlement?','remove the damaged sign by Friday','keep the sign permanently','repaint the storefront next year','A stipulation is a written requirement.'),Q(1,'Which phrase uses the contract sense?','a stipulation of the settlement','a stipulation of sourness','a stipulation of a river','It names a condition included in an agreement.'),Q(1,'How is stipulation related to stipulate?','-ion makes a noun for the requirement','-ion makes a past-tense verb','it is the plural of stipulate','The suffix forms a noun from the verb.','word-formation'),Q(1,'When must the sign be removed?','by Friday','after the company closes forever','before the settlement was signed','The clause states Friday as the deadline.')]);
P('stir','Stir is from Old English styrian, “move or disturb”; it can mean mix liquid, begin moving or rouse a feeling, and a noun for an act or public excitement.',[C('stir.s1','cooking','Stir the soup gently while it warms so the lentils do not stick to the bottom.','汤加热时轻轻搅动，免得扁豆粘在锅底。','stir soup/coffee; stir with a spoon','动词指用勺子或棍子在液体中转动。','The spoon moves through the soup to mix it.','勺子在汤里转动，使其混合。'),C('stir.s2','movement','At dawn the horses began to stir when the stable door opened.','黎明时马厩门一开，马儿便开始活动起来。','stir from sleep; stir into action','动词也指开始移动，或使情感产生强烈反应。','The horses start moving after being still.','马匹原先静止，之后开始活动。'),C('stir.s3','crowds','The surprise announcement caused a stir among the commuters waiting on the platform.','这则突发公告在站台等车的人群中引起了骚动。','cause/create a stir; a public stir','名词指搅动、轰动或人群中的激动不安。','The announcement produces excitement and discussion.','公告引发兴奋和议论。')],M('She stirred the tea by leaving the spoon still and keeping the sugar settled at the bottom.','She stirred the tea by moving the spoon around until the sugar dissolved.','搅拌需要转动勺子并混合液体。','meaning'),[Q(1,'What should the cook do to the soup?','move a spoon through it to mix it','leave it untouched','strain it through a sieve','Stir sense 1 means move a spoon or stick around in liquid.'),Q(2,'What did the horses do at dawn?','began to move','caused a newspaper story','mixed the soup','Sense 2 includes beginning to move.'),Q(3,'What did the announcement cause?','public excitement and discussion','a quiet stable','a jar of stock','A stir is a wave of excitement among people.'),Q(2,'Which sentence uses the movement sense?','The baby stirred when the door creaked.','Stir the sauce with a spoon.','The rumor caused a stir.','The first describes beginning to move.')]);
P('stitch','Stitch is from Old English stice, “a puncture or prick”; it names sewing a seam, one loop of thread, or a sharp side pain during exercise.',[C('stitch.s1','sewing','Mara stitched the torn pocket closed before putting the coat away.','玛拉把破口袋缝好后才收起外套。','stitch cloth together; stitch up a tear','动词指用针线缝合布料或伤口。','Thread joins the two edges of the torn pocket.','线把口袋破口的两边缝在一起。'),C('stitch.s2','sewing','Each stitch was small and even, so the patch lay flat against the sleeve.','每一针都细小均匀，因此补丁平整地贴在袖子上。','a row of stitches; put in a stitch','名词指缝线的一针或伤口上的一针缝合。','A loop of thread holds the patch in place.','一圈线把补丁固定住。'),C('stitch.s3','health','He slowed to a walk when a stitch developed in his side during the race.','比赛中他突然岔气，便放慢脚步改为步行。','get/have a stitch in one’s side','名词还可指跑步时肋侧突然出现的刺痛。','The pain is sharp and begins during exertion.','这种刺痛在运动时突然出现。')],M('She stitched the torn pocket by pulling the needle away without passing thread through either edge.','She stitched the torn pocket by sewing its two edges together with thread.','没有让针线穿过布边就没有缝合。','meaning'),[Q(1,'How did Mara repair the pocket?','sewed the torn edges together','glued a stone to the sleeve','pulled the pocket off','Stitch as a verb means join with needle and thread.'),Q(2,'Why did the patch lie flat?','its stitches were small and even','the pocket was left open','the sleeve had a sharp pain','A stitch can be one loop of thread.'),Q(3,'Why did the runner slow down?','a sudden sharp pain in the side','his coat pocket tore','a crowd caused a stir','A stitch can be a side pain during exercise.'),Q(1,'Which action is “stitch up a tear”?','sew the opening closed','stomp on the fabric','stock a shelf with cloth','The phrase means repair by sewing.')]);
P('stock','Stock traces to Old English stocc, “trunk or support,” with later senses for goods held ready, company shares, cooking liquid, and keeping supplies.',[C('stock.s1','retail','The shop’s stock of winter gloves ran low after the first snowfall.','第一场降雪后，商店的冬季手套库存所剩不多。','in stock/out of stock; replenish stock','名词指商店或仓库备售的货物。','Customers have bought most of the gloves kept for sale.','顾客买走了大部分备售手套。'),C('stock.s2','finance','She bought stock in the small engineering company after reading its annual report.','读完年度报告后，她买入了这家小型工程公司的股票。','buy/sell stock; stock in a company','名词指公司的股份或所有权份额。','Her purchase represents partial ownership of the company.','她的购买代表对公司的部分所有权。'),C('stock.s3','cooking','The cook simmered chicken bones and vegetables to make stock for the stew.','厨师把鸡骨和蔬菜慢炖成炖菜用的高汤。','chicken/vegetable stock; make stock','名词指用肉或蔬菜慢炖出的调味液体。','The simmering ingredients flavor the liquid.','慢炖的食材为液体增添风味。'),C('stock.s4','supply','The clinic stocks extra masks for days when deliveries are delayed.','诊所储备了额外口罩，以备送货延误的日子使用。','stock shelves/products; stock up on','动词表示备有某物以供使用或销售。','Masks are kept available for future demand.','口罩被储备起来以应对之后的需求。')],M('The shop is out of stock of gloves, so the shelf is fully replenished with dozens of pairs.','The shop is out of stock of gloves, so no pairs are available for sale.','货架补满了就不是缺货。','meaning'),[Q(1,'What ran low after the snowfall?','the shop’s supply of winter gloves','the company’s shares','the soup’s cooking liquid','Stock sense 1 is goods held for sale.'),Q(2,'What does buying stock in a company mean?','buying a share of its ownership','buying gloves from a store','making a soup base','Stock sense 2 is a company share.'),Q(3,'How was the stew base made?','bones and vegetables were simmered','gloves were boiled briefly','the company issued shares','Stock can mean flavorful liquid made by simmering food.'),Q(4,'What does the clinic do with extra masks?','keeps them available for later use','sells company shares','turns them into soup','The verb stock means keep a supply ready.')]);
P('stocking','Stocking is from Middle English stocking for a fitted leg covering; today it can mean a close-fitting hosiery item or a decorative Christmas sock for gifts.',[C('stocking.s1','clothing','She wore a warm wool stocking under each boot on the winter hike.','冬季徒步时，她在每只靴子里都穿了一只保暖羊毛长袜。','a pair of stockings; pull on a stocking','名词指贴身覆盖脚和腿的袜类衣物。','The garment covers the foot and leg inside the boot.','这种衣物在靴内覆盖脚和腿。'),C('stocking.s2','holiday','The children hung a red stocking by the fireplace for small Christmas presents.','孩子们在壁炉旁挂了一只红色圣诞袜，准备装小礼物。','hang/fill a Christmas stocking','名词也指圣诞节挂起来装礼物的大袜子。','The decorative sock is left open for gifts.','装饰袜留有开口以放入礼物。')],M('She put on a stocking for the hike, but wore it as a loose scarf around her neck.','She put a close-fitting stocking over her foot and lower leg before the hike.','stocking 是腿脚衣物，不是围巾。','meaning'),[Q(1,'What did she wear under her boots?','a close-fitting leg garment','a Christmas gift bag','a stoneware bowl','Stocking sense 1 is hosiery for the foot and leg.'),Q(2,'Why did the children hang the red stocking?','to hold small Christmas presents','to keep shop inventory','to cover a wound','Sense 2 is a decorative gift holder.'),Q(1,'Which phrase refers to hosiery?','a pair of stockings','stock a stocking list','stitch a stocking of time','The first is the clothing sense.'),Q(2,'Which stocking is hung by a fireplace?','a Christmas stocking','a wool stocking inside a boot','a store’s stocklist','The holiday sense is the decorative sock for gifts.')]);
P('stocklist','Stocklist combines stock + list and names a printed or online inventory of goods a shop or company has available.',C('stocklist.s1','retail','The buyer compared the online stocklist with the warehouse shelves before placing a large order.','采购员下大单前先把在线库存清单与仓库货架逐项核对。','check/update a stocklist; online stocklist','名词指列出商店或公司的现有商品的清单。','The list is used to verify available goods.','这份清单用于核实现有货物。'),M('The buyer checked the stocklist to see what was available, but it contained no product or inventory information.','The buyer checked the stocklist, which listed the available products and quantities.','没有商品库存信息的文件不能充当 stocklist。','meaning'),[Q(1,'What did the buyer compare?','the online inventory list and warehouse shelves','a story and its ending','a set of stone steps','A stocklist records what goods are available.'),Q(1,'What is a stocklist used for?','checking available products','describing a person’s body shape','measuring a river’s width','It lists a shop’s or company’s goods.'),Q(1,'Which verb fits stocklist?','update the stocklist','stomp the stocklist into','stitch a stocklist with','A stocklist can be checked or updated.' ,'collocation'),Q(1,'What two words form stocklist?','stock and list','stock and stone','stop and list','It is a direct compound of stock + list.','word-formation')]);
P('stockpile','Stockpile combines stock + pile; as a verb it means accumulate a large reserve, often because a shortage is expected.',C('stockpile.s1','supplies','The town stockpiled bottled water before the bridge closed for repairs.','桥梁因维修关闭前，镇里储备了大量瓶装水。','stockpile supplies/weapons; stockpile for an emergency','动词表示为将来需要或短缺而大量积存物资。','Water is gathered in advance for a possible interruption.','这些水被提前积存，以应对可能的供应中断。'),M('The town stockpiled water by giving away its entire reserve before the bridge closed.','The town stockpiled water by storing extra bottles ahead of the bridge closure.','把储备全部送走是减少储备，不是积存。','meaning'),[Q(1,'Why did the town gather water?','the bridge might close and disrupt deliveries','the town wanted to empty its reserve','a story needed a new ending','Stockpile means accumulate a reserve.'),Q(1,'What did the town stockpile?','bottled water','a set of stockings','a southerly breeze','The context names water as the stored resource.'),Q(1,'Which phrase is natural?','stockpile food for an emergency','stockpile to food by emergency','a stockpile of time to read','The verb takes the goods being accumulated as its object.' ,'grammar'),Q(1,'How is stockpile formed?','stock plus pile','stocking plus -less','stoma plus pile','The compound suggests a pile kept as a reserve.')]);
P('stocktaking','Stocktaking combines stock + taking and names an inventory count or, figuratively, a pause to assess progress and resources.',[C('stocktaking.s1','business','The shop closes on Tuesday for stocktaking, when staff count every item in the storeroom.','商店周二暂停营业盘点库存，员工会清点储藏室里的每件商品。','annual stocktaking; carry out stocktaking','名词指清点商品存货的盘点工作。','Workers compare the actual goods with the records.','员工将实物与记录核对。'),C('stocktaking.s1','review','At the year’s end, the department took stock of its results before planning the next budget.','年底时，部门先评估工作成果，再编制下一年度预算。','take stock of progress/resources','比喻用法指停下来评估进展或可用资源。','The team reviews its achievements and remaining resources.','团队回顾成果和剩余资源。')],M('The shop completed stocktaking without counting or checking a single item in the storeroom.','The shop completed stocktaking by counting its stored items against the records.','盘点存货必须清点或核对商品。','meaning'),[Q(1,'Why did the shop close Tuesday?','staff needed to count its inventory','it was opening a new story','the stove required a repair','Stocktaking is an inventory count.'),Q(1,'What does “take stock of progress” mean?','review progress and resources','buy shares in a company','stack boxes without checking them','The figurative phrase means assess the current situation.'),Q(1,'Which task belongs to stocktaking?','count every item in the storeroom','write a fictional storyline','stir soup in a pot','Stocktaking compares actual inventory with records.'),Q(1,'What is the compound made from?','stock and taking','stomach and ache','stone and work','The noun names the act of taking inventory.','word-formation')]);
P('stocky','Stocky is stock + -y and describes a person with a thick, solid build who is not very tall.',C('stocky.s1','appearance','The stocky goalkeeper reached the low shot quickly because he had a solid, compact build.','这位矮壮的守门员身材结实紧凑，很快就扑到了低射球。','a stocky build/person; short and stocky','形容词指身材厚实结实而不太高。','His compact frame helps him cover the low goal area.','他紧凑结实的体格便于覆盖球门低处。'),M('The stocky goalkeeper was tall and extremely thin, with no solid or compact build.','The stocky goalkeeper was fairly short with a thick, solid build.','高瘦体形与 stocky“矮壮”不符。','meaning'),[Q(1,'How is the goalkeeper built?','shorter and solidly built','very tall and extremely thin','wide like a bridge span','Stocky describes a thick, compact body.'),Q(1,'Which adjective fits the goalkeeper?','stocky','stoically','stodgy','The source sense describes his body shape.'),Q(1,'What does -y do in stocky?','forms an adjective from stock','makes a plural noun','means without a stock','The ending -y creates the descriptive adjective.' ,'word-formation'),Q(1,'Which phrase is natural?','a stocky build','a stockiness build','a stocky of a person','Stocky is an adjective modifying build.')]);
P('stodgy','Stodgy is from stodge, a word for heavy filling food, with a broader figurative sense for dull, old-fashioned material; the deeper history is uncertain.',[C('stodgy.s1','food','The dense dumpling was stodgy after three servings, so I stopped eating and saved the rest.','吃了三份后，这种厚实的团子让人觉得腻饱，我便停下来把剩下的留着。','stodgy pudding/food; heavy and stodgy','形容词指食物厚重、饱腹而令人发腻或难消化。','The dense meal feels unpleasantly heavy after a few servings.','几份之后，这顿厚重的食物让人觉得腻。'),C('stodgy.s2','writing','The editor cut a stodgy paragraph that repeated old arguments without adding a new idea.','编辑删掉了一段乏味古板的文字，它重复旧论点却没有新意。','stodgy prose/lecture; dull and old-fashioned','形容词也可比喻内容古板、沉闷、缺乏想象力。','The paragraph repeats familiar points and feels dull.','这段文字重复熟悉观点，读起来沉闷。')],M('The stodgy paragraph was lively and imaginative, introducing a fresh idea in every sentence.','The stodgy paragraph was dull and old-fashioned, repeating the same points.','充满新想法和活力与 figurative stodgy 相反。','meaning'),[Q(1,'How did the dumpling feel after several servings?','heavy and filling in an unpleasant way','light and refreshing','crisp and airy','Stodgy sense 1 describes dense, filling food.'),Q(2,'Why did the editor cut the paragraph?','it was dull and repeated old ideas','it was full of imaginative new points','it listed a stock of supplies','The figurative sense means dull and old-fashioned.'),Q(1,'Which phrase uses the food sense?','a stodgy pudding','a stodgy argument','a stodgy lecture','The pudding example is about heavy food.'),Q(2,'What does stodgy suggest of prose?','dull and unimaginative','fresh and brilliant','spatially precise','It describes writing that lacks freshness.')]);
P('stoically','Stoically is stoic + -ally; Stoic comes from the Greek Stoa, the portico associated with the ancient school, and the adverb means enduring hardship calmly without complaint.',C('stoically.s1','resilience','She waited stoically through the long delay, even after the heating failed in the station.','车站暖气坏了后，她仍坚忍地等待，没有抱怨漫长延误。','stoically accept/endure; remain stoically calm','副词修饰承受困难的方式，表示冷静而不抱怨。','She faces discomfort without outward complaint.','她面对不适时没有表现出抱怨。'),M('She waited stoically by shouting complaints every minute and leaving as soon as the train was delayed.','She waited stoically, calmly enduring the delay without complaint.','不断抱怨并立刻离开不符合坚忍承受的方式。','meaning'),[Q(1,'How did she handle the delay?','calmly and without complaint','by shouting every minute','by leaving immediately','Stoically describes calm endurance.'),Q(1,'What made waiting difficult?','the long delay and failed heating','a new stocklist','a story with a happy ending','The station heating failed during the delay.'),Q(1,'Which word is the base of stoically?','stoic','stoma','stoker','Stoically is the adverb form of stoic.' ,'word-formation'),Q(1,'Which sentence shows stoically enduring hardship?','He accepted the setback without complaint.','He celebrated every small success loudly.','He stirred the soup with a spoon.','The first example shows calm endurance.')]);
P('stoker','Stoker is formed from stoke + -er; a stoker’s job is to add coal or wood to a furnace, boiler, or engine fire.',C('stoker.s1','work','The stoker fed coal into the ship’s boiler while the engineers monitored the pressure.','司炉工把煤添进船上的锅炉，工程师则监测压力。','a ship/boiler stoker; work as a stoker','名词指负责给炉膛或锅炉添燃料的人。','Adding coal keeps the boiler fire burning.','添煤使锅炉的火继续燃烧。'),M('The stoker kept the boiler fire going by removing all fuel and refusing to add coal or wood.','The stoker kept the boiler fire going by adding coal to the furnace.','司炉工的职责是添燃料，而非全部撤走燃料。','meaning'),[Q(1,'What did the stoker add to the boiler?','coal','watercolor paint','a pair of stockings','A stoker feeds fuel to a furnace or boiler.'),Q(1,'What did the engineers monitor?','the boiler’s pressure','the stoker’s story','the river’s source','Pressure is named as the engineers’ task.'),Q(1,'What does -er indicate in stoker?','a person who performs the action','a place where coal is stored','a past-tense form','The suffix makes an agent noun from stoke.' ,'word-formation'),Q(1,'Which phrase is natural?','work as a stoker','stoker the boiler with pressure','a stoker of the pressure','A stoker is a worker with a defined job.')]);
P('stoma','Stoma comes from Greek stoma, “mouth”; it names a tiny pore in a plant surface or an opening made in the body by surgery.',[C('stoma.s1','botany','A stoma on the leaf opened in daylight, allowing carbon dioxide to enter for photosynthesis.','叶片上的气孔在白天开放，让二氧化碳进入以进行光合作用。','leaf stoma; stomata on a leaf','名词在植物学中指植物表皮上进行气体交换的小孔。','The pore allows gas to pass through the leaf surface.','这个小孔使气体穿过叶片表面。'),C('stoma.s1','medicine','After surgery, the nurse showed him how to clean the abdominal stoma and attach a pouch.','手术后，护士向他演示如何清洁腹部造口并安装袋子。','surgical/abdominal stoma; care for a stoma','医学义指手术在身体上形成的开口。','The opening provides a route for bodily waste after surgery.','手术后，这个开口为排泄物提供通路。')],M('The nurse called the surgical stoma a leaf pore that lets carbon dioxide enter for photosynthesis.','The nurse called the surgical stoma an opening created in the body after the operation.','手术造口不是植物气孔。','distinction'),[Q(1,'What enters through the leaf stoma?','carbon dioxide','coal for a boiler','water from the stomach','A plant stoma is a pore for gas exchange.'),Q(1,'What does the nurse help the patient care for?','an opening created by surgery','a leaf surface','a boiler furnace','The medical sense is an opening made in the body.'),Q(1,'What is the Greek source word stoma?','mouth','stone','storm','The Greek word means “mouth.”','word-formation'),Q(1,'Which form is the plural of stoma?','stomata','stomas only, never stomata','stomae only','Stomata is the standard botanical plural.' ,'plural')]);
P('stomach','Stomach comes through Old French estomac from Latin stomachus and Greek stomachos; it names the digestive organ or belly, and as a verb means tolerate something unpleasant.',[C('stomach.s1','health','The stomach begins digesting food after it leaves the esophagus.','食物离开食道后，胃开始对其进行消化。','empty/full stomach; stomach acid','名词指食物开始消化的身体器官。','The organ receives food from the esophagus.','这个器官接收来自食道的食物。'),C('stomach.s2','body','He held his stomach after lifting the heavy crate awkwardly.','他笨拙地抬起沉重箱子后，捂住了腹部。','lie on one’s stomach; stomach muscles','名词也可指胸部以下身体前面的腹部。','His hand covers the front of the body below the chest.','他的手捂住胸部以下的身体前侧。'),C('stomach.s3','tolerance','I can’t stomach another meeting that repeats the same argument without a decision.','我无法忍受再开一场重复同样争论却毫无结论的会议。','cannot stomach something; stomach an idea','动词表示能够接受或忍受令人不快的事。','The speaker finds the repeated meeting unacceptable.','说话者无法接受这种重复会议。')],M('She could stomach the bitter medicine because she found its taste completely intolerable and refused to swallow it.','She could stomach the bitter medicine despite its unpleasant taste.','能够忍受与完全不能接受相反。','meaning'),[Q(1,'Where does digestion begin?','in the stomach','in the stockroom','in the stoma of a leaf','The stomach is the organ where food begins to be digested.'),Q(2,'Which body area did he hold?','the front below his chest','his shoulder','his throat only','Stomach can mean the belly.'),Q(3,'What does “can’t stomach another meeting” mean?','cannot tolerate it','will happily host it','will stir it with a spoon','The verb means find something unpleasantly hard to accept.'),Q(3,'Which phrase uses stomach as a verb?','She could not stomach the unfair rule.','She felt pain in her stomach.','Her stomach digested lunch.','The first means she could not tolerate the rule.')]);
P('stomachache','Stomachache combines stomach + ache and names pain in the stomach or belly, often linked to illness, stress, or food.',C('stomachache.s1','health','After eating the unrefrigerated leftovers, Leo developed a stomachache and went home to rest.','吃了未冷藏的剩菜后，利奥胃腹疼痛，回家休息了。','have/get a stomachache; a bad stomachache','名词指胃部或腹部的疼痛。','The discomfort begins after the questionable meal.','不适在吃了可疑剩菜后出现。'),M('Leo had a stomachache, but he felt no pain anywhere in his stomach or belly.','Leo had a stomachache, with pain in his belly after eating the leftovers.','没有腹部疼痛就不符合 stomachache 的含义。','meaning'),[Q(1,'What happened after Leo ate the leftovers?','he developed pain in his belly','he became a stoker','he filled a stocklist','Stomachache means pain in the stomach or belly.'),Q(1,'What did Leo do after the pain began?','went home to rest','went to a public debate','bought company shares','He went home to rest.'),Q(1,'Which phrase is standard?','have a stomachache','have a stomach painache','stomachache on a stomach','The usual collocation is “have a stomachache.”','collocation'),Q(1,'How is stomachache formed?','stomach plus ache','stomach plus -ly','stock plus pile','The compound names an ache in the stomach.')]);
P('stomp','Stomp is a sound-imitative English word; as a verb it means walk with heavy noisy steps, and as a noun it can name one such step.',[C('stomp.s1','movement','The toddler stomped down the hallway in rain boots, leaving muddy prints on the tiles.','幼儿穿着雨靴重重地走过走廊，在瓷砖上留下泥脚印。','stomp around/down; stomp one’s feet','动词指用力跺脚、发出沉重响声地走。','Each step presses hard and makes a noise.','每一步都用力踩下并发出声响。'),C('stomp.s2','sound','One final stomp from the upstairs neighbor shook dust from the ceiling.','楼上邻居最后重重一跺，震得天花板落下灰尘。','a heavy stomp; hear a stomp','名词指一次沉重而响亮的踏步。','A single loud step transmits a vibration through the ceiling.','一次响亮的脚步把震动传到天花板。')],M('The toddler stomped down the hall by tiptoeing silently so that not a tile or floorboard moved.','The toddler stomped down the hall with heavy noisy steps that left muddy prints.','悄声踮脚与 stomp 的沉重响亮动作相反。','meaning'),[Q(1,'How did the toddler walk?','with heavy noisy steps','silently on tiptoe','by sliding on a stocking','Stomp means walk heavily and noisily.'),Q(2,'What shook dust from the ceiling?','one loud step','a mild breeze','a stocktaking count','The noun stomp is a single heavy footstep.'),Q(1,'Which sentence uses stomp as a verb?','He stomped through the puddle.','A stomp echoed from upstairs.','One stomp shook the ceiling.','The first sentence describes the action.'),Q(2,'Which phrase names one loud step?','a final stomp','stomp down the hallway','stomp around the room','A final stomp is the noun sense.')]);
P('stone','Stone is from Old English stān, “stone or rock”; it names rock material, a jewel in jewelry, a fruit pit, and the act of throwing stones at someone.',[C('stone.s1','construction','The wall was built from local stone cut from the hillside quarry.','这面墙用山坡采石场开采的当地石料砌成。','a wall/house of stone; stone quarry','名词指坚硬的矿物质或一块石头。','Blocks of rock form the wall.','岩石块构成了墙体。'),C('stone.s2','jewelry','A small green stone was set in the silver ring her aunt left her.','她姨妈留下的银戒指上镶着一颗绿色宝石。','set a stone in a ring; precious stone','名词也指镶嵌在首饰里的宝石。','The green jewel is mounted in a ring.','绿色宝石镶在戒指上。'),C('stone.s3','fruit','Remove the stone from each peach before blending the fruit into the sauce.','把每个桃子的果核去掉，再把果肉搅成酱。','a peach/cherry stone; stone fruit','名词指桃子等水果中心坚硬的种子。','The hard seed sits in the middle of the peach.','坚硬的种子位于桃子中央。'),C('stone.s4','violence','The crowd was warned not to stone the passing vehicles.','人群被警告不得向驶过的车辆投石。','stone someone/something; be stoned','动词指向某人或某物扔石头。','The warning concerns throwing stones at vehicles.','警告针对向车辆投掷石块。')],M('She removed the peach stone by leaving the hard seed in the fruit and discarding the flesh.','She removed the peach stone by taking out the hard seed from its center.','石头在水果义中是中央的硬核，不是果肉。','meaning'),[Q(1,'What material formed the wall?','local rock','a silver ring','a peach seed','Stone sense 1 is rock material.'),Q(2,'What was set in the ring?','a green jewel','a peach pit','a piece of wall','Sense 2 means a gem used in jewelry.'),Q(3,'What should be removed from the peach?','the hard seed in its center','the stone wall','the silver band','Stone can mean a fruit’s hard central seed.'),Q(4,'What does “stone a vehicle” mean?','throw stones at it','build it from stone','remove its peach pit','The verb means throw stones at a person or place.')]);
P('stonemason','Stonemason combines stone + mason; it names a craftsperson who cuts, shapes, and builds with stone.',C('stonemason.s1','construction','The stonemason carved the arch blocks by hand and fitted them without visible mortar.','石匠手工雕刻拱门石块，并在看不见砂浆的情况下将它们严密拼合。','a skilled stonemason; work as a stonemason','名词指加工石料并用石材建造墙、拱或纪念物的工匠。','The worker shapes and assembles the stone blocks.','工匠加工并组装石块。'),M('The stonemason built the arch by carving and fitting only wooden boards, never working with stone.','The stonemason built the arch by shaping and fitting stone blocks.','只加工木板而不使用石料的人不是此处的石匠。','meaning'),[Q(1,'What did the stonemason carve?','blocks for an arch','a stocklist','a fruit pit','A stonemason shapes stone for construction.'),Q(1,'What is the worker’s craft?','building with shaped stone','managing company shares','stirring a soup','The compound names a craftsperson working with stone.'),Q(1,'Which phrase is natural?','hire a stonemason to repair the wall','hire a stonemason for stocking the shelves','a stonemason of the story line','Stonemasons are hired for stonework.' ,'collocation'),Q(1,'Which words form stonemason?','stone and mason','storm and mason','stomach and stone','It is a compound naming a mason who works in stone.' ,'word-formation')]);
P('stoneware','Stoneware combines stone + ware; it is a dense ceramic fired at high temperature, non-porous but distinct from porcelain.',C('stoneware.s1','pottery','The potter fired the stoneware mug until it became dense and non-porous.','陶艺师把炻器马克杯烧制到致密且不透水。','stoneware dish/crock; fire stoneware','名词指高温烧制、致密不透水但并非瓷器的陶器。','High firing makes the ceramic dense and water-resistant.','高温烧制使陶器致密并能防水。'),M('The potter called the porous low-fired earthen cup stoneware even though it absorbed water through its walls.','The potter called the dense, high-fired, non-porous mug stoneware.','多孔、低温烧制的陶器不符合 stoneware 的材料特征。','distinction'),[Q(1,'What happened during firing?','the mug became dense and non-porous','it remained porous earthenware','it turned into a silver jewel','Stoneware is fired hot enough to become dense.'),Q(1,'How is stoneware different from porcelain?','it is a distinct ceramic category, not porcelain','it is a soft liquid','it is always made of natural stone','Stoneware is non-porous but is not porcelain.'),Q(1,'Which item could be stoneware?','a high-fired crock','a loose stocking','a company share','Stoneware is a type of ceramic ware.'),Q(1,'What does ware mean in this compound?','manufactured goods or articles','a person who cuts stone','a sharp stomach pain','Ware names goods or articles.')]);
})();

(function(){
'use strict';
const D=globalThis.RA.D;
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('stonework','Stonework combines stone + work and means masonry or the stone components of a structure.',C('stonework.s1','building','The restoration team matched the new stonework to the original blocks around the courthouse doorway.','修复团队让新砌的石作与法院门口原有石块相吻合。','stonework on a wall; repair stonework','名词指石材砌筑工程或建筑中的石质部分。','The work adds and repairs fitted stone elements.','这项工程添加并修复拼合的石质构件。'),M('The crew called the new stonework a masonry repair even though every new piece was made only of plastic.','The crew called the fitted stone blocks stonework because they formed a masonry repair.','全用塑料制作不属于石材砌筑或石作。','meaning'),[Q(1,'What did the restoration team match?','new masonry to the original stone blocks','a stocking to a storelist','a storm to a storyline','Stonework means masonry or stone elements.'),Q(1,'Where was the repaired stonework?','around the courthouse doorway','inside a stomach','on a computer screen','The context places it at the doorway.'),Q(1,'Which phrase uses stonework naturally?','repair the stonework on the arch','stir the stonework in the pot','stockpile a stonework of books','Stonework is built or repaired as masonry.' ,'collocation'),Q(1,'Which words form stonework?','stone and work','storm and story','stoma and work','The compound names work done in stone.')]);
P('stony','Stony is stone + -y and describes ground full of stones or a person’s expression or manner as hard and unfeeling.',[C('stony.s1','landscape','The hikers crossed stony ground where loose rocks shifted beneath their boots.','徒步者穿过多石的地面，松动的石块在靴底下滑动。','stony path/ground; stony soil','形容词指布满石头的地方或土地。','Loose stones cover the surface.','地表覆盖着松动的石块。'),C('stony.s1','emotion','He gave the reporter a stony look and refused to comment on the accusation.','他冷漠地看了记者一眼，拒绝评论这项指控。','a stony expression/look; stony silence','形容词比喻表情或态度冷硬、缺少感情。','His face gives no warmth or visible response.','他的脸上没有亲切感或明显回应。')],M('The hikers crossed stony ground that was smooth, soft, and entirely free of rocks.','The hikers crossed stony ground covered with loose rocks.','没有石头的柔软地面不能称为 stony。','meaning'),[Q(1,'What made the path difficult?','loose stones shifted underfoot','the path was soft and empty','a damaged stove blocked it','Stony ground is covered with stones.'),Q(1,'How did he respond to the reporter?','with a cold, unfeeling look','with a warm smile','by telling a long story','Stony can describe an emotionally hard expression.'),Q(1,'Which phrase uses the landscape sense?','a stony trail across the ridge','a stony silence after the question','a stony reply to the reporter','The trail phrase refers to ground covered with stones.'),Q(1,'What is the base of stony?','stone','storm','stock','The adjective is formed from stone plus -y.','word-formation')]);
P('stool','Stool is from Old English stōl, “seat”; it names a seat without a back or arms and, in medical language, solid waste passed from the body.',[C('stool.s1','furniture','The child pulled a wooden stool beside the counter so she could reach the sink.','孩子把木凳拉到柜台边，好够到水槽。','sit on a stool; a bar/kitchen stool','名词指没有靠背和扶手的座椅。','The child uses the small seat to gain height.','孩子用小座位垫高身体。'),C('stool.s2','medicine','The nurse asked him to bring a stool sample to the clinic in the sealed container.','护士让他把密封容器里的粪便样本带到诊所。','stool sample; pass stool','医学名词指从身体排出的固体排泄物。','The sample is collected for medical testing.','样本被收集起来作医学检测。')],M('The clinic requested a stool sample, and the patient brought a wooden seat for testing.','The clinic requested a stool sample, meaning a small sample of solid body waste.','医学义 stool 指排泄物，不是木凳。','distinction'),[Q(1,'What did the child use to reach the sink?','a seat without a back or arms','a sealed medical container','a pile of stone blocks','A stool is a simple seat.'),Q(2,'What did the nurse request?','a sample of solid body waste','a kitchen chair','a stocklist','The medical sense means feces.'),Q(1,'Which phrase uses the furniture sense?','sit on a wooden stool','bring a stool sample to the clinic','pass stool for testing','The first refers to a seat.'),Q(2,'What should a patient bring in the sealed container?','a stool sample','a small chair','a strip of stonework','The phrase means a medical sample of excrement.')]);
P('stoop','Stoop is from Old English stūpian, “bend or bow”; it means bend the upper body, lower oneself to an unworthy act, or name a bent posture or a small porch.',[C('stoop.s1','movement','She stooped to pick up the dropped key without bending her knees.','她弯下身子捡起掉落的钥匙，没有屈膝。','stoop to pick up; stoop down','动词指上身向前、向下弯。','Her torso bends toward the key.','她的躯干朝钥匙弯下。'),C('stoop.s2','conduct','He would not stoop to copying a rival’s proposal, even under pressure to meet the deadline.','即使在赶截止日期的压力下，他也不屑于抄袭对手的提案。','stoop to doing something; stoop so low','动词也指屈尊或堕落到自认为不光彩的行为。','He considers copying beneath his standards.','他认为抄袭有失自己的操守。'),C('stoop.s3','posture','Years of back pain left him with a stoop when he stood for long periods.','多年的背痛使他久站时不得不弯腰驼背。','walk with a stoop; a stoop in the back','名词可指弯腰姿势。','His upper body bends forward while standing.','他站立时上身向前弯。'),C('stoop.s3','architecture','We left our boots on the small stoop outside the front door.','我们把靴子留在前门外的小门廊上。','front stoop; sit on the stoop','名词也指住宅入口处的小门廊或台阶。','The shoes remain on the raised entrance platform.','鞋子留在入口的台阶平台上。')],M('She stooped to pick up the key by keeping her torso upright and reaching with a long pole.','She stooped to pick up the key by bending her upper body forward and down.','上身保持直立、用杆子够取并不是弯腰。','meaning'),[Q(1,'How did she get the key?','bent her upper body toward it','stood upright and used a pole','sat on a stool','Stoop as a verb means bend forward and down.'),Q(2,'What would he not stoop to do?','copy a rival’s proposal','meet the deadline honestly','walk up the front steps','The second sense means lower oneself to an unworthy act.'),Q(3,'What did the back pain cause?','a bent posture','a small porch','a stone wall','Stoop as a noun can name a hunched posture.'),Q(3,'Where did they leave their boots?','on the small porch at the entrance','on a chair without a back','in the riverbed','The architectural noun means a small entry porch.')]);
P('stop','Stop comes through Old English stoppian, “block or close”; it means cease moving or acting, prevent someone’s action, or name a regular transit point.',[C('stop.s1','activity','The technician stopped the conveyor before clearing the jammed carton.','技术员先停下传送带，再清理卡住的纸箱。','stop moving/working; stop doing something','动词指不再移动或继续某项活动。','The conveyor ceases operation before maintenance.','传送带在维修前停止运转。'),C('stop.s2','prevention','A steel barrier stopped cars from entering the pedestrian lane.','钢制护栏阻止汽车驶入步行道。','stop someone from doing; stop an object','动词也指阻止某人做某事或阻拦某物。','The barrier prevents cars from entering.','护栏阻挡汽车驶入。'),C('stop.s3','transport','We got off at the next bus stop, opposite the public library.','我们在下一站下了车，车站就在公共图书馆对面。','bus/train stop; make a stop','名词指公交车或火车定期停靠的地点。','The bus halts at a scheduled place.','公交车在固定地点停靠。')],M('The technician stopped the conveyor by letting it continue to carry boxes while the jam remained.','The technician stopped the conveyor before removing the jammed carton.','让机器继续运转不算使其停止。','meaning'),[Q(1,'What did the technician do before clearing the jam?','ceased the conveyor’s movement','allowed the belt to keep running','got off at a bus stop','Stop sense 1 means cease operation.'),Q(2,'What did the barrier prevent?','cars entering the pedestrian lane','people leaving a bus','the conveyor from stopping','Stop can mean prevent an action.'),Q(3,'Where did the passengers get off?','at a regular bus halting place','at the conveyor belt','inside a storefront','A stop is a place where a bus regularly halts.'),Q(2,'Which construction means prevent a person’s action?','stop someone from entering','stop at the bus stop','stop working permanently','The pattern is stop + person + from + -ing.')]);
P('stop working','Stop working combines stop + working; it can mean retire permanently from a job or, of a machine, cease operating because of a fault or lost power.',[C('stop working.s1','retirement','After thirty-five years at the clinic, Dr. Shah decided to stop working and spend more time with her grandchildren.','在诊所工作三十五年后，沙医生决定退休，多陪陪孙辈。','stop working at a certain age; decide to stop working','短语表示永久结束职业工作，常因年龄或退休而发生。','She leaves the workforce after a long career.','她结束长期职业生涯，离开工作岗位。'),C('stop working.s2','machines','The freezer stopped working overnight, so the restaurant moved the food to a backup unit.','冰柜夜里停止运转，因此餐馆把食物转移到备用设备。','the engine/machine stops working','指机器因故障或断电而不再运行。','The freezer no longer operates, requiring a backup.','冰柜不再运转，需要备用设备。')],M('The freezer stopped working, but it continued cooling food normally all night with no power or fault.','The freezer stopped working when its compressor failed overnight.','正常持续制冷与停止运转相矛盾。','meaning'),[Q(1,'What did Dr. Shah decide to do?','retire from her job','repair the freezer','take a short lunch break','Here the phrase means permanently leave work.'),Q(2,'Why did the restaurant move its food?','the freezer had ceased operating','the doctor retired','the stocklist was updated','A machine that stops working no longer operates.'),Q(1,'Which sense is about retirement?','Dr. Shah stopped working after a long career.','The freezer stopped working overnight.','The stove stopped heating briefly.','The first is a person permanently ending a career.'),Q(2,'Which clue signals the machine sense?','the freezer moved food to a backup unit','the doctor spent time with grandchildren','the clinic hired a new physician','A backup is needed because the appliance failed.')]);
P('stopgap','Stopgap combines stop + gap and names a temporary substitute that fills a need but is not a lasting solution.',C('stopgap.s1','planning','A borrowed generator served as a stopgap until the town’s damaged power line was repaired.','在镇上的受损电线修好前，借来的发电机暂时代替供电。','a temporary stopgap; stopgap measure','名词指填补空缺、暂时应急但不能长久解决问题的办法。','The generator covers the need only until permanent repairs are done.','发电机只在永久维修完成前满足需求。'),M('The borrowed generator was a stopgap solution that permanently repaired the town’s power line.','The borrowed generator was a stopgap until permanent repairs could be completed.','临时替代方案本身没有永久修好电线。','meaning'),[Q(1,'What was the borrowed generator?','a temporary substitute','the permanent repaired power line','a store’s regular stock','Stopgap means a short-term solution.'),Q(1,'How long did it serve?','until the power line was repaired','forever after the repairs','before any electricity was needed','A stopgap fills the need only temporarily.'),Q(1,'Which phrase is natural?','a stopgap measure','a stopgap permanently solution','stopgap the town with','The noun commonly modifies measure or solution.' ,'collocation'),Q(1,'What does the compound suggest?','closing a gap temporarily','stopping all work permanently','a gap made of stone','The word names a temporary filler for a gap.')]);
P('stopper','Stopper is stop + -er; it names a plug closing a bottle or something that blocks a pipe, hole, or passage.',[C('stopper.s1','bottles','She pushed the cork stopper firmly into the bottle before packing it for the picnic.','她把软木塞紧紧塞进瓶口，再把瓶子装进野餐篮。','cork/bottle stopper; remove the stopper','名词指塞进瓶口以封闭容器的塞子。','The cork closes the opening and keeps liquid inside.','软木塞封住瓶口，防止液体流出。'),C('stopper.s2','plumbing','A wad of roots acted as a stopper in the drain and sent water back into the sink.','一团树根堵住了排水管，使水倒流进水槽。','a stopper in a pipe; act as a stopper','名词也可指堵住管道或孔洞的东西。','The roots block the pipe and prevent flow.','树根堵住管道，使水流无法通过。')],M('The bottle stopper kept the juice inside by leaving the bottle mouth completely open.','The bottle stopper kept the juice inside by sealing the opening.','敞开的瓶口没有被塞子封住。','meaning'),[Q(1,'What did she push into the bottle?','a cork plug','a drainpipe','a stoneware mug','A stopper closes a bottle opening.'),Q(2,'What blocked the drain?','a wad of roots','a cork in a bottle','a storey of a building','Sense 2 is anything that blocks a passage.'),Q(1,'Which phrase refers to the bottle sense?','remove the cork stopper','a stopper in the drain','the root stopper sent water back','The first names the plug closing a bottle.'),Q(2,'What did the roots do?','prevented water from flowing through the pipe','sealed the juice bottle','stopped a story from ending','The second sense is a blockage in a pipe.')]);
P('storage','Storage is store + -age and names keeping items or information for later, the place or capacity used for it, or a computer system’s data-holding part.',[C('storage.s1','records','Proper storage kept the signed contracts dry and organized until the audit.','妥善保管让签署后的合同在审计前保持干燥且有序。','in storage; safe/proper storage','名词指把货物、文件或信息留存以备日后使用。','The documents are kept safely for later retrieval.','文件被安全保存以供之后查找。'),C('storage.s2','space','The apartment has extra storage under the stairs for suitcases and cleaning supplies.','公寓楼梯下有额外储物空间，可放行李箱和清洁用品。','storage space; a storage area','名词也指建筑中存放物品的空间或场所。','The enclosed area holds household objects.','封闭空间用于放置家用物品。'),C('storage.s3','computing','The tablet has enough storage for the maps and recordings needed on the trip.','这台平板有足够存储空间，保存旅途中需要的地图和录音。','data/storage capacity; cloud storage','计算机义指保存正在使用或已存下的信息的系统部分。','Files remain available in the device’s memory.','文件保存在设备存储器中以便使用。')],M('The tablet has ample storage, but it cannot retain any maps or recordings once the screen is closed.','The tablet has ample storage, so it retains the maps and recordings for later use.','存储的用途正是留住数据供之后使用。','meaning'),[Q(1,'How were the contracts kept?','dry and organized for later use','in a storm outside','inside a bottle stopper','Storage sense 1 is the act of keeping things for later.'),Q(2,'Where can the suitcases go?','under-stair storage space','the computer memory','the storefront window','Sense 2 means a physical place for keeping objects.'),Q(3,'What can the tablet’s storage hold?','maps and recordings','a physical suitcase under stairs','a contract audit room','Digital storage retains files.'),Q(2,'Which phrase uses the physical-space sense?','extra storage under the stairs','cloud storage for recordings','storage of signed contracts','The first refers to a place in a building.')]);
P('store','Store came through Old French estorer, related to Latin instaurare, “restore or furnish”; it names a shop, the act of keeping something, or a reserve for future use.',[C('store.s1','retail','The store on Elm Street sells repair tools and closes at six on weekdays.','榆树街上的商店出售维修工具，工作日六点关门。','a grocery/book store; go to the store','名词指出售商品的地方。','Customers buy tools at this retail location.','顾客在这个零售地点购买工具。'),C('store.s2','preservation','Store the spare batteries in a cool, dry drawer until the radio needs them.','把备用电池放在阴凉干燥的抽屉里，等收音机需要时再用。','store food/data safely; store something away','动词表示把物品留存到以后需要时再用。','The batteries are kept for future use.','电池被留作将来使用。'),C('store.s3','reserve','The village keeps a store of emergency blankets in the community hall.','村里在社区礼堂储备了一批应急毯子。','a store of supplies/knowledge','名词也可指为未来使用而储备的数量。','The blankets form a reserve ready for emergencies.','这些毯子构成随时可用的应急储备。')],M('The village kept a store of emergency blankets, but none were held in reserve or available when needed.','The village kept a store of blankets ready for residents during emergencies.','store of supplies means a reserve, so none being available contradicts the claim.','meaning'),[Q(1,'What does the shop on Elm Street sell?','repair tools','storylines','computer memory','Store sense 1 is a retail shop.'),Q(2,'Why keep batteries in a drawer?','to preserve them until they are needed','to sell them at a bookstore','to turn them into stock','The verb means keep something for later use.'),Q(3,'What does the village keep in the hall?','a reserve of emergency blankets','a retail storefront','a story about a storm','A store of something can mean a supply or reserve.'),Q(2,'Which use is a verb?','Store the batteries in a dry place.','The store closes at six.','A store of blankets is ready.','The first has store as an action.')]);
P('storefront','Storefront combines store + front and names the street-facing side of a shop, including its display windows and entrance.',C('storefront.s1','retail','The bakery painted its storefront blue and added a ramp beside the entrance.','面包店把临街店面漆成蓝色，并在入口旁加装了坡道。','shop/storefront window; renovate a storefront','名词指商店朝街的一面，包括橱窗和入口。','The paint and ramp change the visible street-facing side.','油漆和坡道改造了面向街道的一面。'),M('The bakery renovated its storefront, but the work was entirely inside the basement and did not affect the street-facing side.','The bakery renovated the windows and entrance on its street-facing side.','storefront 指面向街道的外部，而不是地下室内部。','meaning'),[Q(1,'Which part did the bakery paint?','the street-facing shop exterior','the basement floor','the storeroom shelf','A storefront is the street-facing side of a shop.'),Q(1,'What else did the bakery add?','a ramp beside the entrance','a stockpile under the stairs','a story about a stoker','The example mentions an entrance ramp.'),Q(1,'Which phrase uses storefront naturally?','repair a cracked storefront window','storefront a box for later','a storefront of emergency blankets','The storefront includes the shop window.' ,'collocation'),Q(1,'What does front mean in storefront?','the side facing the street','the rear storeroom','the top floor','The compound names the visible front of a shop.')]);
P('storehouse','Storehouse combines store + house and names a large building where goods or equipment are kept until needed.',C('storehouse.s1','logistics','The coastal storehouse held grain and spare nets until the fishing boats returned.','渔船返航前，海边仓库储存谷物和备用渔网。','a grain/storehouse; keep goods in a storehouse','名词指储放货物或设备的大型建筑。','The building protects supplies until they are needed.','建筑把物资保存到需要时。'),M('The coastal storehouse kept no goods or equipment; it was used only as an open public swimming pool.','The coastal storehouse held grain and nets for the fishing crews.','不储存物资的泳池不是仓库。','meaning'),[Q(1,'What was stored in the coastal building?','grain and spare nets','stomach samples','a story’s characters','A storehouse is a large storage building.'),Q(1,'When were the supplies needed?','when the fishing boats returned','before the house was built','during the next story only','The goods were kept until the crews came back.'),Q(1,'Which phrase is natural?','keep equipment in a storehouse','storehouse a net until return','a storehouse of stony silence','The building is a place to keep goods.' ,'collocation'),Q(1,'How is storehouse formed?','store plus house','storm plus house','story plus -less','The compound means a house-like building for storage.')]);
P('storeroom','Storeroom combines store + room and names a room used to keep supplies rather than to live or sell goods.',C('storeroom.s1','workplace','The laboratory keeps spare gloves and glassware in a locked storeroom behind the reception desk.','实验室把备用手套和玻璃器皿放在接待台后面上锁的库房里。','a supply storeroom; keep equipment in a storeroom','名词指专门存放设备、食物或库存的房间。','The room holds supplies rather than serving customers or residents.','房间用于放物资，而非接待顾客或居住。'),M('The laboratory called its storeroom a supply room, although it contained no stored items and was used as a dining hall.','The laboratory used the locked room to store gloves and glassware.','没有存放物品且用作餐厅的房间不符合 storeroom 的用途。','meaning'),[Q(1,'Where were the spare gloves kept?','in a locked supply room','on the street-facing storefront','in the stomach','A storeroom is a room for stored supplies.'),Q(1,'What else did the lab keep there?','glassware','a bus stop','a story ending','The context mentions glassware.'),Q(1,'Which activity belongs in a storeroom?','storing equipment','selling goods to customers','living overnight','The room is for storage rather than selling or living.'),Q(1,'What words make storeroom?','store and room','stone and room','storm and room','The compound means a room for storage.' ,'word-formation')]);
P('storey','Storey is the British spelling for one level of a building; the architectural word has a separate history from story meaning a tale.',[C('storey.s1','architecture','Their flat occupies the third storey above the bakery and faces the quiet courtyard.','他们的公寓位于面包店上方的第三层，朝向安静的庭院。','a two-storey house; on the upper storey','名词指建筑中的一层楼。','The flat is on the building’s third level.','公寓位于建筑的第三个楼层。'),C('storey.s2','building height','The proposed hotel is a twelve-storey building with shops at ground level.','拟建酒店是一栋十二层建筑，底层设有商铺。','a ten-storey block/building','名词也用于描述建筑有多少层。','Twelve storeys give the hotel its height description.','十二层用来描述酒店的高度。')],M('The twelve-storey hotel has only one level above the ground-floor shops.','The twelve-storey hotel has twelve levels, including the ground floor.','“十二层建筑”不能同时只有一层。','number'),[Q(1,'Where is the flat?','on the building’s third level','in the third story of a novel','below the bakery in its cellar','Storey sense 1 means a floor of a building.'),Q(2,'How high is the proposed hotel?','twelve levels','one level','twelve stories told aloud','Storey can describe a building’s number of floors.'),Q(1,'Which spelling refers to a building level in British English?','storey','storyline','storie','Storey is the British spelling for a floor.' ,'spelling'),Q(2,'What does the architectural term count?','the building’s floors','the chapters in a tale','the number of storerooms','It counts levels in a building.')]);
P('storm','Storm is from Old English storm, a Germanic word for violent weather; it names severe weather and as a verb means attack suddenly or move away angrily.',[C('storm.s1','weather','The storm brought strong winds and heavy rain that closed the coastal road.','暴风雨带来强风和大雨，导致沿海公路关闭。','a rain/snow storm; weather the storm','名词指伴有强风和雨雪的恶劣天气。','The wind and rain make travel unsafe.','强风和大雨使出行不安全。'),C('storm.s2','attack','Protesters stormed the empty hall after the doors were forced open.','门被强行打开后，抗议者冲进了空大厅。','storm a building/fortress; storm into','动词指突然且强力地攻击或闯入某处。','The group enters the hall forcefully.','人群强行进入大厅。'),C('storm.s3','anger','He stormed out of the office after the argument about the missing files.','因丢失文件的问题发生争吵后，他怒气冲冲地离开办公室。','storm out of a room; storm away','动词也指愤怒地走开。','His angry departure follows the argument.','争吵后他愤怒地离开。')],M('The protesters stormed the hall by walking in quietly after receiving a formal invitation.','The protesters stormed the hall by forcing their way inside.','受邀安静进入不是突然强行闯入。','meaning'),[Q(1,'Why did the coastal road close?','strong winds and heavy rain','a new storey','a calm sunny afternoon','Storm sense 1 is severe weather.'),Q(2,'How did the protesters enter the hall?','suddenly and forcefully','quietly with an invitation','by closing the storm shutters','Storm as a verb can mean attack or enter by force.'),Q(3,'Why did he leave the office?','he was angry after an argument','he was going to buy a storm','he found a storeroom','Storm out means leave angrily.'),Q(1,'Which sentence uses storm as a noun?','A storm closed the coastal road.','They stormed the hall.','He stormed out of the office.','The first names the weather event.')]);
P('stormy','Stormy is storm + -y; it describes violent weather or, figuratively, angry and noisy disagreement.',[C('stormy.s1','weather','A stormy night brought hail and gusts that rattled the shutters.','暴风雨之夜带来冰雹和阵风，震得百叶窗作响。','stormy weather/sea; a stormy night','形容词指有强风、暴雨或暴雪的天气。','Hail and gusts make the night rough.','冰雹和阵风使夜晚天气恶劣。'),C('stormy.s2','relationships','The committee had a stormy debate over the budget, with several members interrupting each other.','委员会就预算展开激烈辩论，几名成员互相打断。','a stormy relationship/debate; stormy temper','形容词比喻争论或脾气愤怒、嘈杂且充满分歧。','The discussion is heated and full of disagreement.','讨论激烈，充满分歧。')],M('The committee’s stormy debate was quiet, friendly, and free of disagreement.','The committee’s stormy debate was angry and full of interruptions.','平和无争议的讨论不是 stormy 的比喻义。','meaning'),[Q(1,'What happened on the stormy night?','hail and gusts rattled the shutters','the air stayed perfectly calm','the committee counted its stock','Stormy sense 1 is rough weather.'),Q(2,'What made the committee debate stormy?','members angrily interrupted one another','everyone agreed silently','the rain filled the storeroom','The figurative sense means heated and full of disagreement.'),Q(1,'Which phrase refers to weather?','a stormy sea','a stormy argument','a stormy relationship','The sea phrase describes rough weather.'),Q(2,'Which phrase uses the figurative sense?','a stormy debate','a stormy night with hail','stormy winds by the coast','A debate can be stormy when it is heated.')]);
P('story','Story comes from Old French estoire and Latin historia, “history or account”; it means a narrative, a news report, or—by a separate architectural usage—a building level.',[C('story.s1','narrative','Grandfather told a story about the night he first crossed the mountain pass.','祖父讲了一个关于自己首次翻越山口那晚的故事。','tell/read a story; a true/fictional story','名词指对真实或想象事件的叙述。','The account recounts events from the past.','这段叙述讲述过去发生的事。'),C('story.s2','news','The local paper ran a story about the new bridge opening on Monday.','当地报纸刊登了一篇关于新桥周一开放的报道。','a news/story in the paper; cover a story','名词也可指报纸或电视上的新闻报道。','The paper reports a current event.','报纸报道了一件当前事件。'),C('story.s3','architecture','Their office is on the fifth story of the building, above the clinic.','他们的办公室在诊所上方的五楼。','a five-story building; on the upper story','在美式英语中，story 也可指建筑的一层。','The office occupies the building’s fifth level.','办公室位于建筑第五层。')],M('The newspaper ran a story about the bridge, but it was a floor of the building rather than a news report.','The newspaper ran a story reporting the bridge’s Monday opening.','在报纸里 ran a story 指新闻报道，不是楼层。','distinction'),[Q(1,'What did Grandfather recount?','events from his first mountain crossing','a weather forecast','a building’s fifth floor','Story sense 1 is a narrative.'),Q(2,'What did the local paper publish?','a news report about the bridge','a fictional tale from a grandfather','a new storey plan','Story can mean a report in a newspaper.'),Q(3,'Where is their office?','on the building’s fifth level','inside a newspaper article','at the front entrance','In American usage story can mean a floor.'),Q(2,'Which phrase uses story for journalism?','run a story in the local paper','tell a story to a child','a five-story building','The first means publish a news report.')]);
P('storyline','Storyline combines story + line and names the connected sequence of events that forms a book, film, or play’s main plot.',C('storyline.s1','film','The reviewer praised the film’s storyline because the clues from the opening scene mattered at the end.','影评人称赞了电影的情节主线，因为开场的线索在结尾发挥了作用。','follow/develop a storyline; main storyline','名词指构成叙事作品的连贯事件序列。','Early clues connect to the eventual resolution.','早期线索与最终结局相连。'),M('The film’s storyline had no connected events; every scene was unrelated to the next.','The film’s storyline connected the early clues to the final resolution.','彼此无关的场景没有构成连贯情节。','meaning'),[Q(1,'Why did the reviewer praise the storyline?','early clues mattered at the ending','the scenes had no connection','the film contained a storehouse','A storyline is the connected sequence of events.'),Q(1,'What does a storyline organize?','events in a book, film, or play','items in a shop inventory','the levels of a building','It describes the plot’s connected events.'),Q(1,'Which phrase is natural?','develop the main storyline','storyline the plot by','a storyline of a storming','A storyline can be developed through connected events.' ,'collocation'),Q(1,'What does line suggest in storyline?','a sequence of connected events','a physical thread in a stocking','a pipe stopper','It metaphorically refers to the plot’s sequence.')]);
P('storyteller','Storyteller combines story + tell + -er and names someone who recounts tales orally or in writing.',C('storyteller.s1','performance','The storyteller held the children’s attention by changing her voice for each character.','说书人给每个角色变换声音，牢牢吸引了孩子们。','a gifted/storyteller; oral storyteller','名词指讲述故事的人，可以是口头表演者或作者。','Her voice helps her recount the tale to listeners.','她用声音向听众讲述故事。'),M('The storyteller kept the children engaged by refusing to tell, write, or recount any story.','The storyteller kept the children engaged by narrating a tale in different voices.','从不讲述故事的人不是说书人。','meaning'),[Q(1,'How did she keep children listening?','changed her voice for each character','read a stocklist aloud','stopped the story before it began','A storyteller recounts a tale for an audience.'),Q(1,'Who is a storyteller?','someone who recounts tales','a person who repairs stone walls','a machine that stores data','The noun names a narrator or oral performer.'),Q(1,'Which phrase is natural?','a gifted storyteller','a storyteller of a stocking list','storytelling storytellered','The adjective gifted naturally modifies the noun.' ,'grammar'),Q(1,'What does -er mark in storyteller?','a person who tells stories','a room for storing stories','the past tense of tell','The suffix forms an agent noun.')]);
P('storytelling','Storytelling combines story + telling and names the art or practice of recounting events as a story.',C('storytelling.s1','communication','The museum uses storytelling to explain how families lived in the old harbor district.','博物馆用叙事方式讲解老港区家庭的生活。','oral/digital storytelling; use storytelling to','名词指把事件组织并讲述成故事的艺术或实践。','The museum presents historical events as a narrative.','博物馆把历史事件组织成叙述。'),M('The museum used storytelling to explain local history, but displayed no narrative, events, or spoken account at all.','The museum used storytelling by presenting local events as connected narratives.','没有叙述或故事化呈现就没有使用 storytelling。','meaning'),[Q(1,'How does the museum explain local history?','by presenting events as narratives','by counting every storeroom item','by blocking the harbor road','Storytelling is the practice of recounting events as a story.'),Q(1,'Which activity is storytelling?','an oral account of a family’s past','a list of building levels','a single stocking stitch','The first recounts events in narrative form.'),Q(1,'Which phrase is natural?','use storytelling to teach history','storytelling the history with no account','a storytelling of inventory counts','The noun commonly follows “use” and can introduce its purpose.' ,'collocation'),Q(1,'What two elements form storytelling?','story and telling','storm and closing','stock and list','The compound names the act of telling stories.' ,'word-formation')]);
})();

(function(){
'use strict';
const D=globalThis.RA.D;
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('stout','Stout came through Old French estout, “brave or proud,” with an uncertain deeper Germanic history; English describes a solid build, strength, or a dark strong beer.',[C('stout.s1','appearance','The stout hiker carried the pack easily, thanks to his strong, broad frame.','这位身材粗壮的徒步者凭借结实宽阔的体格轻松背起行囊。','a stout build/person; short and stout','形容词指体格结实、较粗壮，常不算高。','His solid body makes the pack manageable.','他结实的体格使背包不难负担。'),C('stout.s2','materials','The carpenter chose stout oak boards for the workbench because they would not bend under pressure.','木匠为工作台选了结实厚重的橡木板，因为它们受压也不会弯曲。','stout rope/wood; a stout defense','形容词也可表示坚固耐用，或态度坚定。','The thick boards withstand force.','厚木板能承受压力。'),C('stout.s3','drink','The pub served a dark stout with roasted malt and a creamy head.','酒吧供应一种烘烤麦芽风味、泡沫绵密的深色黑啤酒。','a pint/glass of stout; dark stout','名词指一种颜色深、味道浓的啤酒。','The drink is identified by its dark malt flavor.','这种啤酒以深色麦芽风味为特征。')],M('The carpenter called a thin brittle board stout even though it bent under the weight of a book.','The carpenter chose a thick, strong board that resisted bending.','容易弯断的薄板不结实耐用。','meaning'),[Q(1,'What was the hiker’s build like?','solid and broad','very thin and fragile','like a narrow sea channel','Stout sense 1 describes a strong, solid build.'),Q(2,'Why choose stout oak boards?','they resist bending under pressure','they are easy to break','they make a stormy sound','Sense 2 means strong and durable.'),Q(3,'What did the pub serve?','a dark strong beer','a small bottle stopper','a vegetable broth','Stout is also a dark beer.'),Q(2,'Which phrase uses stout for durability?','a stout rope for towing','a stout person in a coat','a glass of stout','The rope phrase refers to strength.')]);
P('stove','Stove is recorded in English for a heated room or appliance; its deeper route is uncertain. Today it names a cooking device or a closed wood- or coal-burning heater.',[C('stove.s1','cooking','She turned off the stove after the soup reached a gentle simmer.','汤小火煨好后，她关掉了炉灶。','gas/electric stove; turn on/off the stove','名词指带炉头或烤箱、用于烹饪的设备。','The device heats the soup in a pot.','这个设备加热锅中的汤。'),C('stove.s2','heating','The cabin’s wood stove kept the room warm through the freezing night.','木炉让小屋在严寒夜里保持温暖。','wood/coal stove; heat a room with a stove','名词也可指燃烧木材或煤炭的封闭式取暖炉。','The heater burns wood to warm the cabin.','取暖炉燃烧木材为小屋供暖。')],M('She cooked soup on the stove after disconnecting it so it could not produce any heat.','She cooked soup on the stove while its burner heated the pot.','断开且不产热的设备不能加热烹饪。','meaning'),[Q(1,'What did she turn off after simmering the soup?','the cooking appliance','the storeroom door','the wood-burning heater only','Stove sense 1 is a device for cooking.'),Q(2,'How did the cabin stay warm?','a wood-burning heater supplied heat','the cooking pot cooled the room','the story closed the door','Sense 2 is a stove used for heating.'),Q(1,'Which item typically has burners?','a cooking stove','a strainer','a strap','Burners are part of a cooking stove.'),Q(2,'Which stove burns wood in a cabin?','a closed heater','a stocklist','a sidewalk','The second sense is a wood- or coal-burning heater.')]);
P('stow','Stow is from Old English stowian, “place or put”; it means arrange objects safely inside a vehicle, ship, or room.',C('stow.s1','travel','Please stow your bag under the seat before the train leaves the platform.','列车离开站台前，请把包妥善放在座位下方。','stow luggage/gear; stow something away','及物动词表示把物品放进空间并整理好，使其稳妥不碍事。','The bag is placed securely under the seat.','包被稳妥放在座椅下。'),M('The passengers stowed their bags safely by leaving them loose in the aisle where people could trip over them.','The passengers stowed their bags under the seats, clear of the aisle.','堵住通道且易绊倒乘客的放法并不安全妥当。','meaning'),[Q(1,'Where should the passenger put the bag?','under the seat','in the aisle','on the train platform','To stow is to put something away safely.'),Q(1,'Why should it be stowed?','to keep it secure and out of the way','to block people walking','to make the seat disappear','Stowing arranges objects so they fit safely.'),Q(1,'Which construction is natural?','stow luggage under a seat','stow under luggage a seat','stow a seat into luggage','Stow takes the object followed by its place.' ,'grammar'),Q(1,'What is the basic action in stow?','put and arrange objects in a space','bend the upper body','walk with noisy steps','The verb means put away or load neatly.')]);
P('straggle','Straggle is related to strag, “wander away,” with uncertain deeper origin; it means fall behind a group or spread unevenly over an area.',[C('straggle.s1','walking','Two hikers straggled behind the group after stopping to treat a blister.','两名徒步者停下来处理水泡后，落在了队伍后面。','straggle behind; straggle along','动词指行走缓慢、掉在其他人后面。','The pair move more slowly than the rest.','两人比其他队员走得慢。'),C('straggle.s2','plants','Wild roses straggled along the fence instead of growing in a neat row.','野玫瑰沿着围栏零散蔓延，没有整齐地排成一行。','straggle across/along; plants straggle','动词也指杂乱、不均匀地散布或蔓延。','The plants spread unevenly along the fence.','植物沿围栏不均匀地生长。')],M('The two hikers straggled behind by reaching the summit first and waiting for the others to catch up.','The two hikers straggled behind by moving slowly and falling several minutes back.','先到达山顶意味着领先而不是落后。','meaning'),[Q(1,'Why were two hikers behind?','they stopped and walked more slowly','they reached the summit first','they led the group uphill','Straggle behind means fall back from a group.'),Q(2,'How did the roses grow?','unevenly along the fence','in a perfectly straight row','inside a storage cupboard','Straggle can mean spread untidily over an area.'),Q(1,'Which phrase uses the group-movement sense?','straggle behind the other hikers','roses straggle along the fence','a storyline straggles into chapters','The first describes people falling behind.'),Q(2,'Which sentence uses the uneven-spread sense?','Vines straggled over the old wall.','The hikers straggled behind.','She stowed a bag under a seat.','Vines spread irregularly over the wall.')]);
P('straight','Straight comes from Old English streht, the past participle of streccan, “stretch”; it describes an unbent line, immediate action, honesty, or an uninterrupted sequence.',[C('straight.s1','shape','Draw a straight line between the two marked points without bending the ruler.','用直尺在两个标记点之间画一条直线，不要弯曲尺子。','a straight road/line; keep something straight','形容词指不弯曲、不倾斜。','The line connects the points without a curve.','线段不带弯曲地连接两点。'),C('straight.s2','direction','After the gate, go straight to the reception desk without turning into the courtyard.','过了大门后直接去接待台，不要拐进庭院。','go/come straight to; straight ahead','副词表示直接前往或立即进行，不绕道。','The route has no turn before reception.','去接待处的路线上无需转弯。'),C('straight.s3','honesty','Please give me a straight answer about whether the file was changed.','请坦率告诉我文件是否被改过。','a straight answer; be straight with someone','形容词也指诚实坦率，或连续不间断地发生。','The speaker wants an honest reply without evasion.','说话者要的是不回避的诚实答复。')],M('The ruler drew a straight line that curved twice around the marked points.','The ruler drew an unbent line directly between the marked points.','弯曲的线不是笔直的线。','meaning'),[Q(1,'What kind of line should be drawn?','one without a bend','one with two curves','one that returns to the start','Straight sense 1 means not bent or curved.'),Q(2,'Where should the visitor go after the gate?','directly to reception','turn into the courtyard first','walk back to the road','Straight as an adverb means directly without turning.'),Q(3,'What kind of answer is requested?','honest and direct','long and evasive','a physical straightedge','Straight can mean honest and not evasive.'),Q(2,'Which phrase uses the adverb sense?','go straight to the desk','draw a straight line','give a straight answer','The first indicates direct movement.')]);
P('straightaway','Straightaway combines straight + away and means immediately, without delay.',C('straightaway.s1','timing','The caretaker called the electrician straightaway when sparks appeared at the fuse box.','保险丝盒冒出火花后，管理员立即打电话叫来了电工。','call/act straightaway; do something straightaway','副词表示立刻、毫不拖延地采取行动。','The call happens as soon as the hazard appears.','危险一出现就马上打电话。'),M('The caretaker called the electrician straightaway, waiting three weeks before making the call.','The caretaker called the electrician straightaway as soon as the sparks appeared.','等待三周与立即行动相反。','meaning'),[Q(1,'When did the caretaker call?','as soon as sparks appeared','three weeks later','after the electrician left','Straightaway means immediately.'),Q(1,'Why was help called?','sparks appeared at the fuse box','the storey count changed','a story ended','The sparks created an immediate hazard.'),Q(1,'Which word is a close synonym?','immediately','eventually','rarely','Straightaway means without delay.'),Q(1,'Which phrase is natural?','call the electrician straightaway','straightaway call to the electrician after three weeks','make a straightaway of the call','The adverb modifies the timing of the call.')]);
P('straighten','Straighten is straight + -en and means remove a bend or disorder, or make oneself upright.',[C('straighten.s1','repair','He straightened the bent bracket with a vice before reattaching it to the shelf.','他用台钳把弯曲的托架弄直，然后重新装到架子上。','straighten a wire/leg; straighten out a problem','及物动词表示使弯曲物变直，也可整理或解决混乱。','The vice removes the bend from the bracket.','台钳把托架弯曲处压直。'),C('straighten.s1','posture','She straightened when the interviewer entered and greeted him.','面试官进来时，她挺直了身子并向他问好。','straighten up; straighten one’s back','不及物用法表示身体从弯曲姿势变直。','Her body becomes upright as she stands to greet him.','她起身问候时身体挺直。')],M('He straightened the bracket by bending it farther out of shape with the vice.','He straightened the bracket by pressing the bend flat in the vice.','进一步弯曲会加重变形，而不是使其变直。','meaning'),[Q(1,'What did the vice do to the bracket?','removed its bend','bent it farther','turned it into a stopper','Straighten means make a bent object straight.'),Q(1,'How did she react to the interviewer?','stood upright','slouched lower','stowed the chair','Straighten can mean make one’s body upright.'),Q(1,'Which phrase is natural?','straighten out a misunderstanding','straighten a misunderstanding outly','make a straightening of a misunderstanding','Straighten out can mean resolve a problem.' ,'collocation'),Q(1,'What does -en do in straighten?','forms a verb meaning make straight','forms a plural noun','means without a straight line','The suffix can form a verb meaning make or become.')]);
P('straightforward','Straightforward combines straight + forward and describes something easy to understand or do, or a person who is honest and direct.',[C('straightforward.s1','instructions','The setup is straightforward: connect the cable, press the button, and follow the screen prompts.','安装过程很简单：连接电缆、按下按钮，再按照屏幕提示操作。','a straightforward process/task; straightforward to use','形容词指容易理解或完成，没有隐藏难题。','The steps are short and clear.','这些步骤简短而清楚。'),C('straightforward.s2','communication','The manager was straightforward about the delay and explained exactly what had gone wrong.','经理坦率说明了延误，并准确解释出了什么问题。','be straightforward with someone; a straightforward answer','形容词也指诚实、直率、不试图隐瞒。','The manager gives the facts without evasion.','经理直截了当地说明事实。')],M('The setup was straightforward, with hidden steps, confusing controls, and no clear instructions.','The setup was straightforward because each step was clear and easy to follow.','隐藏复杂步骤与简单明了的过程相反。','meaning'),[Q(1,'Why is the setup straightforward?','the steps are short and clear','it contains hidden controls','the cable is impossible to connect','Sense 1 means easy to do or understand.'),Q(2,'How did the manager discuss the delay?','honestly and directly','by concealing every fact','by telling a fictional story','Sense 2 means honest and direct.'),Q(1,'Which phrase uses the simple-process sense?','a straightforward way to install the app','a straightforward answer from the manager','be straightforward with a colleague','The first refers to an easy process.'),Q(2,'Which phrase uses the honest-person sense?','a straightforward explanation of the error','a straightforward three-step setup','a straightforward road','The explanation is direct and candid.')]);
P('strain','Strain comes through Old French estreindre from Latin stringere, “draw tight”; it means injure or overuse, pressure or tension, a type or variety, or filter liquid.',[C('strain.s1','health','She strained her shoulder while lifting a heavy suitcase into the overhead rack.','她把沉重行李箱举上头顶行李架时拉伤了肩膀。','strain a muscle/back; strain oneself','动词指肌肉因过度用力而受伤，也可表示竭力使用。','Lifting puts excessive force on the shoulder.','举起重物使肩膀承受过大力量。'),C('strain.s2','pressure','The extra night shifts put a strain on the nurses’ family lives.','额外的夜班给护士们的家庭生活带来了压力。','put/place a strain on; under strain','名词指由忧虑、工作或力量造成的压力或紧张。','More work makes home routines harder to manage.','更多工作让家庭安排更难维持。'),C('strain.s3','biology','Researchers tested a strain of wheat that can tolerate salty soil.','研究人员测试了一种能够耐受盐碱土的小麦品系。','a strain of bacteria/wheat; resistant strain','名词指某类植物、动物或疾病的特定类型。','The wheat variety has a particular inherited trait.','这种小麦品系具有特定遗传特征。'),C('strain.s4','cooking','Strain the broth through a fine sieve to remove the herbs and bone fragments.','把高汤用细筛过滤，去除香草和骨屑。','strain liquid through a sieve; strain off solids','动词指把液体倒过过滤物，让固体被拦住。','The sieve holds back the solids while broth passes through.','筛网拦住固体，让高汤流过。')],M('She strained her shoulder while lifting the suitcase, but her shoulder was not used or loaded at all.','She strained her shoulder by lifting more weight than it could comfortably handle.','完全没有用到肩膀就不可能因举重拉伤。','meaning'),[Q(1,'What happened while she lifted the suitcase?','she injured her shoulder muscle','she filtered the broth','she tested a wheat variety','Strain as a verb can injure a muscle through overuse.'),Q(2,'What did night shifts put on family life?','pressure and tension','a kind of wheat','a layer of stoneware','A strain is pressure caused by work or worry.'),Q(3,'What did researchers test?','a particular wheat variety','a muscle injury','a cooking sieve','Strain can mean a type of plant or disease.'),Q(4,'What should the cook do with the broth?','pour it through a sieve to hold solids back','stir in all the bone fragments','leave it unfiltered in the stockroom','Strain sense 4 means filter liquid.')]);
P('strainer','Strainer is strain + -er and names a perforated bowl-shaped kitchen tool that holds solid pieces while liquid passes through.',C('strainer.s1','cooking','She poured the cooked pasta into a strainer so the water drained into the sink.','她把煮好的意大利面倒进滤盆，让水流进水槽。','kitchen/tea strainer; pour through a strainer','名词指带小孔、过滤液体并留下固体的工具。','The holes let water pass but retain pasta.','孔洞让水通过，同时留下意大利面。'),M('She used a strainer to drain the pasta, but its solid bowl had no holes and trapped all the water with it.','She used a perforated strainer that held the pasta while water drained through.','没有孔的实心碗不会让水通过过滤。','meaning'),[Q(1,'What did the strainer let pass?','the cooking water','the solid pasta','a storey of the building','A strainer holds solids while liquid drains away.'),Q(1,'What remained in the bowl?','the pasta','the drained water only','the stovetop','The pasta was retained by the tool.'),Q(1,'Which phrase is natural?','pour pasta into a strainer','strain the strainer through pasta','a strainer of story','A strainer is a tool used to drain pasta.' ,'collocation'),Q(1,'How is strainer formed?','strain plus -er','straight plus -en','straw plus -berry','The suffix -er names a device that performs the action.')]);
P('strait','Strait comes through Old French estreit from Latin strictus, “narrow”; it names a narrow sea passage or, in plural phrase “straits,” a difficult situation.',[C('strait.s1','geography','The ferry crossed the strait between the island and the mainland in forty minutes.','渡船用了四十分钟穿过岛屿与大陆之间的海峡。','a narrow strait; cross/navigate a strait','名词指连接两片较大水域的狭窄海域。','The channel links larger areas of water.','这条水道连接两片较大的水域。'),C('strait.s2','finance','After the factory closed, the family was in dire straits and had to sell its car.','工厂关闭后，这家人陷入困境，不得不卖掉汽车。','in dire/financial straits; fall into straits','复数常用于固定短语，指尤其缺钱的艰难处境。','Losing income leaves the family in a serious difficulty.','收入减少使这家人陷入严重困难。')],M('The ferry crossed the strait, a wide open ocean with no narrow channel between the waters.','The ferry crossed the narrow sea passage linking the island and mainland.','宽阔无边的海洋不是狭窄海峡。','meaning'),[Q(1,'What did the ferry cross?','a narrow sea passage','a family’s financial problem','a stony trail','A strait joins two larger areas of water.'),Q(2,'Why was the family in dire straits?','the factory closed and income was lost','the ferry arrived early','they bought a new stove','The phrase means a very difficult situation.'),Q(1,'Which phrase names the geographic feature?','the strait between the island and mainland','in financial straits','a strategy for the ferry','The first uses strait as a singular sea channel.'),Q(2,'Which expression is idiomatic for hardship?','in dire straits','on a dire strait','strait into a difficult','“In dire straits” is the fixed phrase for serious difficulty.' ,'collocation')]);
P('strand','Strand has distinct histories across senses: the verb “leave aground” is related to Old Norse strand, “shore,” while a strand of thread is a thin piece; it can also mean an idea thread or a shore.',[C('strand.s1','travel','The broken bus stranded the passengers beside the highway until a replacement arrived.','公交车抛锚后，乘客被困在公路旁，直到替换车辆到来。','be stranded on an island; strand a vehicle','动词指使人或车辆滞留在无法离开的地方。','The passengers cannot continue their journey.','乘客无法继续旅程。'),C('strand.s2','materials','One strand of wire had snapped, so the technician replaced the whole cable.','一股金属线断了，因此技术员更换了整根电缆。','a strand of hair/thread/wire; twist strands together','名词指头发、线或金属丝中的一股细长部分。','The broken wire is one thin component of a larger cable.','断掉的金属线是电缆中的一股细线。'),C('strand.s3','ideas','The final chapter brings together the historical and personal strands of the argument.','最后一章把论证中的历史线索和个人经历线索结合起来。','a strand of an argument/story; key strands','名词也可指故事或观点中的一条线索，或海岸。','Different threads of the argument are combined.','论证的不同线索被结合起来。')],M('The broken bus stranded its passengers by delivering them safely to their destination with no delay.','The broken bus stranded its passengers by leaving them unable to continue beside the highway.','顺利送达目的地不构成滞留。','meaning'),[Q(1,'What happened after the bus broke down?','passengers were left unable to continue','the vehicle reached its destination','a cable strand snapped','Strand as a verb means leave someone stuck.'),Q(2,'What snapped in the cable?','one thin wire component','the whole highway','a strand of the argument','A strand can be one thread or wire in a bundle.'),Q(3,'What did the final chapter bring together?','two lines of argument','the stranded bus and passengers','the shore and ferry','A strand can be a thread of an idea.'),Q(1,'Which sentence uses the verb?','The storm stranded the sailors on the island.','A strand of hair fell on the coat.','One strand of the story was forgotten.','The first says people were left unable to leave.')]);
P('strange','Strange came through Old French estrange from Latin extraneus, “foreign or outside”; it means unusual or difficult to explain, or unfamiliar to someone.',[C('strange.s1','events','A strange noise came from the empty storeroom, although no one was inside.','空无一人的储藏室里传出奇怪的声音。','a strange sound/idea; strange behavior','形容词指不寻常、难以解释的。','The sound is unexpected and has no obvious cause.','声音出乎意料且没有明显原因。'),C('strange.s2','familiarity','The streets felt strange to us because we had arrived in the city only that morning.','这些街道让我们觉得陌生，因为我们当天早晨才到这座城市。','strange to someone; feel strange in a place','形容词也指某人不认识或没有经历过的。','The visitors have not yet learned their way around.','访客还不熟悉当地路线。')],M('The street felt strange to the visitors, although they had lived there for decades and knew every corner.','The street felt strange to the visitors because they had arrived that morning.','长期熟悉且认识每个角落与陌生感相反。','meaning'),[Q(1,'Why was the noise strange?','it came from an empty room with no clear cause','it was the usual sound of a busy kitchen','the visitors had just arrived','Strange sense 1 means unusual or hard to explain.'),Q(2,'Why did the streets feel strange?','the visitors had just arrived','they had lived there for decades','the storm was over','Sense 2 means unfamiliar to a person.'),Q(1,'Which phrase uses the unusual sense?','a strange noise in an empty room','a strange street to a newcomer','a strange city to visitors','The first describes an unexplained sound.'),Q(2,'Which phrase uses the unfamiliarity sense?','The layout was strange to us.','A strange noise echoed.','Strange behavior puzzled the staff.','The first means the layout was not familiar.')]);
P('stranger','Stranger is formed from strange + -er and names someone not known to you or unfamiliar with a place or activity.',C('stranger.s1','safety','A stranger offered to carry the child’s bag, so the parent thanked him but stayed close.','一位陌生人提出帮孩子拿包，家长谢过他但仍陪在孩子身边。','a complete stranger; talk to a stranger','名词指自己不认识的人，或不熟悉某地或活动的人。','The parent does not know the person offering help.','家长不认识这位主动帮忙的人。'),M('The woman was a stranger to the family because she had lived with them and known them for years.','The woman was a stranger to the family because they had never met her before.','多年共同生活就不再是陌生人。','meaning'),[Q(1,'Who offered to carry the bag?','someone the parent did not know','the child’s mother','the stonemason','A stranger is an unfamiliar person.'),Q(1,'Why did the parent stay close?','the person was unknown to the family','the bag was a stocklist','the child had a stomachache','The parent is cautious around an unfamiliar person.'),Q(1,'Which phrase is natural?','a complete stranger','a strange-er person','a stranger of strange','The noun stranger names an unknown person.'),Q(1,'How is stranger formed?','strange plus -er','stove plus -er','strait plus -age','Here -er forms a person noun from strange.','word-formation')]);
P('strangle','Strangle comes through Old French estrangler from Latin strangulare; it means injure or kill by pressure on the throat, or figuratively suppress an activity or plan.',[C('strangle.s1','safety','The emergency instructor demonstrated how pressure on the neck can strangle a person and warned students never to try it.','急救教员演示了颈部受压会如何造成窒息，并提醒学生绝不可尝试。','strangle someone; be strangled by','动词指用力压迫喉部造成伤害或死亡。','The pressure blocks normal breathing.','这种压力妨碍正常呼吸。'),C('strangle.s2','figurative','Excessive paperwork can strangle a small project before the team has time to test it.','过多文书工作可能在团队来得及测试前就扼杀一个小项目。','strangle growth/creativity; strangle a plan','比喻用法指阻止计划、情绪或活动发展。','The paperwork prevents the project from progressing.','文书工作阻碍项目推进。')],M('The paperwork strangled the project by giving the team more time and resources to develop it.','The paperwork strangled the project by delaying every trial until funding ran out.','提供时间和资源会支持项目而非扼杀它。','meaning'),[Q(1,'What physical danger does the instructor describe?','pressure on the throat can block breathing','a storm can close a road','a strap can hold luggage','Strangle sense 1 concerns pressure on the neck.'),Q(2,'What could paperwork do to a project?','prevent it from developing','give it unlimited resources','make it a stranger','Figuratively, strangle means suppress growth or activity.'),Q(1,'Which sentence uses the literal sense?','The attacker tried to strangle the victim.','Red tape strangled the proposal.','The plant strangles the fence metaphorically.','The first describes pressure on a person’s throat.'),Q(2,'Which phrase uses the figurative sense?','strangle a new business with needless rules','strangle someone’s throat','be strangled by a cable physically','The first describes preventing an activity from succeeding.')]);
P('strap','Strap is recorded in Middle English for a narrow band used to bind or carry; its deeper origin is uncertain. It is a band or the act of fastening with one.',[C('strap.s1','equipment','The camera strap was wide enough to spread the weight across her shoulder.','相机带足够宽，可以把重量分散到她的肩膀上。','a shoulder/leather strap; adjust a strap','名词指用于固定或携带物品的窄带。','The band supports the camera on her shoulder.','带子把相机托在肩上。'),C('strap.s2','packing','They strapped the boxes to the roof rack before driving across the pass.','他们出发穿越山口前，把箱子用带子固定在车顶架上。','strap something to a rack; strap in','动词指用带子捆住或系牢人或物。','The straps keep the boxes from shifting.','带子防止箱子滑动。')],M('They strapped the boxes to the roof rack by leaving them loose and unsecured during the drive.','They strapped the boxes tightly to the roof rack so they could not slide off.','松散未固定不算用带子捆牢。','meaning'),[Q(1,'What rested on her shoulder?','a band carrying the camera','a strainer full of pasta','a story from the newspaper','A strap is a narrow band used to carry or hold something.'),Q(2,'How were the boxes secured?','fastened to the rack with straps','left loose on the roof','stored in a storeroom','The verb means fasten with a strap.'),Q(1,'Which phrase uses strap as a noun?','adjust the camera strap','strap the boxes to the rack','strap in before takeoff','The first names the band itself.'),Q(2,'Which phrase uses strap as a verb?','strap the package to the cart','a leather strap on a bag','the strap’s width','The first describes fastening an object.')]);
P('stratagem','Stratagem comes from Greek stratēgēma, “a general’s act or maneuver,” from stratēgos, “general”; it is a plan designed to gain an advantage, sometimes by deception.',C('stratagem.s1','competition','The chess player used a stratagem to lure her opponent into protecting the wrong square.','棋手用了一个巧计，引诱对手去防守错误的棋格。','a clever stratagem; devise/use a stratagem','名词指为取得优势而设计的策略，有时带误导性。','The apparent threat distracts the opponent from the actual plan.','表面威胁让对手忽视真正的计划。'),M('The chess stratagem gained an advantage by openly explaining every move and removing all uncertainty for the opponent.','The chess stratagem gained an advantage by leading the opponent to defend the wrong square.','完全揭示计划会失去误导对手的效果。','meaning'),[Q(1,'What did the chess player’s stratagem do?','led the opponent to defend the wrong square','gave the opponent every answer','repaired a broken strap','A stratagem is a plan used to gain an advantage.'),Q(1,'Can a stratagem involve misleading someone?','yes, it sometimes does','no, it always states every move','it only names a weather event','The source sense allows a deceptive scheme.'),Q(1,'Which phrase is natural?','devise a stratagem','stratagem the opponent to','a stratagem of a strategy’s','One devises or uses a stratagem.' ,'collocation'),Q(1,'Which Greek root is behind stratagem?','stratēgos, “general”','stoma, “mouth”','stān, “stone”','The word began in the language of military command.' ,'word-formation')]);
P('strategic','Strategic is strategy + -ic and means connected with a general plan or important to a long-term aim.',C('strategic.s1','planning','The bridge is at a strategic point where the highway crosses the only river for miles.','这座桥位于战略要地，公路在数英里范围内唯一的过河点横穿河流。','a strategic location/decision; strategic importance','形容词指与总体计划相关或对长期目标很重要。','Control of this crossing affects the whole route.','控制这个渡口会影响整条路线。'),M('The bridge was strategic, but its location had no effect on the route, access, or any long-term plan.','The bridge was strategic because the highway had no other crossing for miles.','没有任何战略影响的地点不能称为战略要地。','meaning'),[Q(1,'Why is the bridge at a strategic point?','it is the only highway crossing for miles','it is a small stool','it has a stormy storyline','Its location is important to access and route planning.'),Q(1,'What does strategic describe?','importance to a broader plan','a single noisy footstep','a kind of stoneware','Strategic relates to a general plan or long-term aim.'),Q(1,'Which collocation is natural?','a strategic decision','a strategically decision','a strategic of point','Strategic is an adjective modifying decision.' ,'grammar'),Q(1,'What is the base noun?','strategy','stranger','strait','Strategic is formed from strategy with -ic.' ,'word-formation')]);
P('strategist','Strategist is strategy + -ist and names someone who designs plans for war, politics, business, or sport.',C('strategist.s1','business','The campaign strategist shifted the budget toward neighborhoods where turnout was lowest.','竞选策略师把预算转向投票率最低的社区。','political/business strategist; serve as a strategist','名词指设计战略或总体计划的人。','She analyzes the campaign and plans where to focus resources.','她分析竞选情况并规划资源重点。'),M('The campaign strategist designed no plan and made no decisions about how to reach voters.','The campaign strategist planned where to focus the budget to reach more voters.','不制定任何计划的人不符合 strategist 的职责。','meaning'),[Q(1,'What did the strategist decide?','where the campaign budget should focus','which stove to turn off','how to describe a storm','A strategist designs plans and resource priorities.'),Q(1,'Which person is a strategist?','someone who plans a campaign’s approach','a person who repairs stone blocks only','a passerby no one knows','A strategist designs strategy.'),Q(1,'Which phrase is natural?','a campaign strategist','a strategist the campaign on','strategyist for campaign','The noun labels the person who plans.' ,'grammar'),Q(1,'How is strategist formed?','strategy plus -ist','straight plus -er','strap plus -age','-ist forms a person noun for someone involved in strategy.')]);
P('strategy','Strategy comes from Greek stratēgia, “generalship,” from stratēgos, “general”; it is a careful plan for reaching a goal or the skill of planning a military contest.',[C('strategy.s1','business','Their strategy for reducing delays is to schedule deliveries outside the morning rush.','他们减少延误的策略是在早高峰以外安排送货。','a strategy for doing something; develop a strategy','名词指为达到目标而制定的周密计划。','The delivery plan is chosen to reduce delays.','送货安排旨在减少延误。'),C('strategy.s2','military','The commander explained the strategy for holding the bridge until reinforcements arrived.','指挥官说明了在援军到达前守住桥梁的战略。','military strategy; strategy in a contest','名词也指规划如何赢得战争或大型竞赛的本领。','The plan coordinates defense until help arrives.','该计划协调防守直到援军到来。')],M('Their strategy reduced delays by scheduling every delivery directly in the morning rush.','Their strategy reduced delays by scheduling deliveries outside the morning rush.','把送货安排在最拥堵时段会增加而非减少延误。','meaning'),[Q(1,'What is the company’s plan?','schedule deliveries outside rush hour','hold a bridge until reinforcements arrive','repair a stove','Strategy sense 1 is a plan to reach a goal.'),Q(2,'What must the commander plan?','how to hold the bridge until help arrives','how to sell the company’s shares','how to store pasta','Sense 2 is military or contest planning.'),Q(1,'Which phrase is natural?','develop a strategy for reducing delays','strategy to reducing delays for','a strategic of delay','A strategy for doing something is a common pattern.' ,'collocation'),Q(2,'Which phrase uses strategy in the military sense?','a strategy for defending the bridge','a strategy for delivery times','a strategy in a cooking recipe','The first is about military defense.')]);
})();

(function(){
'use strict';
const D=globalThis.RA.D;
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('stratification','Stratification is stratify + -ation; stratify derives from Latin stratum, “layer,” from sternere, “spread out.” The noun describes layers in rock, water, or society.',[C('stratification.s1','geology','The geologist examined the stratification in the cliff, where pale sandstone lay above dark shale.','地质学家检查了峭壁中的地层，浅色砂岩位于深色页岩之上。','rock/water stratification; layers of stratification','名词指岩石、水体或社会被分成不同层次的状态或过程。','The visible rock layers show how the deposits accumulated.','可见岩层呈现沉积物累积的层次。'),C('stratification.s1','society','The report described income stratification between the city’s central and outer districts.','报告描述了该市中心区和外围区之间的收入分层。','social/class stratification; stratification by income','社会学义指群体依照地位或收入形成不同层级。','Residents are grouped into different income levels.','居民被划分为不同收入层级。')],M('The report found no income stratification because every household had exactly the same income and status.','The report found clear income stratification, with households grouped at different income levels.','各群体完全相同就不存在收入分层。','meaning'),[Q(1,'What did the geologist observe?','different layers of sandstone and shale','one uniform block of rock','a stocklist of minerals','Stratification is the arrangement into distinct layers.'),Q(1,'What does income stratification describe?','groups at different income levels','a riverbed with no layers','a single person’s muscle strength','Social stratification divides society into levels.'),Q(1,'What does -ation form in stratification?','a noun for a process or result','a person who stratifies','an adjective meaning unlayered','The suffix forms an abstract noun from stratify.' ,'word-formation'),Q(1,'Which phrase uses the geological sense?','stratification in the cliff face','stratification by household income','social stratification across districts','The first refers to rock layers.')]);
P('stratify','Stratify is stratum + -ify, from Latin stratum, “something spread out”; it means divide material, a sample, or society into distinct layers.',C('stratify.s1','research','The analyst stratified the survey sample by age so that each decade was represented.','分析员按年龄对调查样本分层，确保每个十年年龄段都有代表。','stratify a sample by age; stratify data','及物动词指把总体分成不同层级或层次。','The age groups are separated before the sample is analyzed.','分析前先把年龄组分开。'),M('The analyst stratified the sample by age while combining every age group into a single undivided category.','The analyst stratified the sample by separating respondents into age groups.','把所有年龄合成一个类别不是分层。','meaning'),[Q(1,'How did the analyst divide the survey?','into age groups','into a single undivided group','into a kitchen strainer','Stratify means divide into distinct layers or categories.'),Q(1,'Why stratify the sample?','to represent each decade of age','to prevent all participation','to change the survey’s storyline','The example says each decade should be represented.'),Q(1,'Which construction is natural?','stratify the sample by age','stratify by the sample to age','stratification the sample by age','The verb takes the sample as object and uses “by” for the grouping basis.' ,'grammar'),Q(1,'What does -ify contribute?','forms a verb meaning make or divide into','forms a plural of stratum','means without layers','-ify forms a verb from the layer noun.')]);
P('stratigraphy','Stratigraphy combines Latin stratum, “layer,” with Greek -graphia, “description or study”; it is the geological study of strata and their sequence.',C('stratigraphy.s1','geology','The team used stratigraphy to determine which fossil layer was deposited before the volcanic ash.','团队借助地层学判断哪一层化石沉积在火山灰之前。','study/use stratigraphy; stratigraphy of a region','名词指描述岩层及其沉积先后顺序的地质学分支。','The relative position of the strata establishes their order.','地层的相对位置帮助确定先后顺序。'),M('The geologist used stratigraphy to study the order of rock layers, but the report says the field examines only modern street traffic.','The geologist used stratigraphy to study the arrangement and order of rock layers.','地层学研究岩层，不是街道交通。','meaning'),[Q(1,'What did stratigraphy help establish?','the order in which layers were deposited','the storey count of a building','the age of a streetcar','Stratigraphy studies strata and their sequence.'),Q(1,'What is stratigraphy a branch of?','geology','cooking','computer storage','The source definition identifies it as a geological field.'),Q(1,'Which subject belongs in stratigraphy?','the position of fossil-bearing strata','the best way to stopper a bottle','the meaning of a story','Stratigraphy examines rock layers and their order.'),Q(1,'What does -graphia contribute?','study or description','a layer of rock','a person who studies','The compound combines “layer” with a study/description element.' ,'word-formation')]);
P('stratosphere','Stratosphere combines strato-, from stratum “layer,” with sphere; the term names the stable atmospheric layer above most weather.',C('stratosphere.s1','atmosphere','A research balloon climbed into the stratosphere, above the clouds and most storms.','科研气球升入平流层，位于云层和大多数风暴之上。','in the stratosphere; stratospheric layer','名词指位于对流层上方、天气较稳定的大气层。','The balloon rises above the region where most weather occurs.','气球升到大多数天气现象发生的区域上方。'),M('The balloon entered the stratosphere while remaining below the clouds in the part of the atmosphere where storms form.','The balloon entered the stratosphere above the clouds and most weather systems.','大多数云和风暴位于较低的大气层。','distinction'),[Q(1,'Where did the balloon rise?','above most clouds and storms','below all clouds in a storm','into the ocean strait','The stratosphere lies above the layer where most weather occurs.'),Q(1,'What does the prefix strato- suggest?','layers','stars','street traffic','It is related to stratum, “layer.”','word-formation'),Q(1,'Which phrase refers to the atmospheric layer?','the upper stratosphere','the third storey','a stratum of society only','The first names a part of the atmosphere.'),Q(1,'What is generally true of the stratosphere?','it is more stable than the weather layer below','it contains all surface storms','it is a deep ocean channel','It lies above most weather activity.')]);
P('stratum','Stratum is Latin for “something spread out” or “layer,” from sternere; it names a horizontal layer of material or a social level.',[C('stratum.s1','geology','The lower stratum of sandstone was older than the ash layer above it.','下方的砂岩层比上面的火山灰层更古老。','a stratum of rock/soil; lower/upper stratum','名词指岩石或其他材料形成的水平层。','Its position beneath another layer indicates relative age.','它位于另一层之下，说明了相对年代。'),C('stratum.s2','society','The policy was designed to help a stratum of workers whose wages had fallen behind inflation.','这项政策旨在帮助一部分工资落后于通胀的劳动者。','a stratum of society; upper/lower stratum','名词也指具有相似地位或收入的社会阶层。','The workers share a similar economic position.','这些劳动者处于相近的经济地位。')],M('The lower geological stratum lay above the younger ash, despite the report calling it the oldest layer beneath it.','The lower sandstone stratum lay beneath the ash and was older.','下层在上、上层更老与给定地层顺序相反。','meaning'),[Q(1,'Which layer was older?','the lower sandstone layer','the upper ash layer','the topsoil in another field','A stratum is a distinct material layer.'),Q(2,'Which workers did the policy target?','a social level sharing similar wage conditions','one geological layer','all workers equally regardless of income','Stratum can name a level of society.'),Q(1,'What is the singular of strata?','stratum','strata','stratums only','Stratum is singular; strata is its common plural.' ,'plural'),Q(2,'Which phrase uses the social sense?','a stratum of workers','a stratum of sandstone','the lower stratum in a cliff','The first describes a group sharing social or economic position.')]);
P('straw','Straw is from Old English strēaw, “dried stalk”; it names dry cereal stems and, in modern use, a thin tube for drinking.',[C('straw.s1','farming','The farmer spread straw over the muddy path to keep boots from sinking.','农夫把稻草铺在泥泞小路上，防止靴子陷进去。','a bale of straw; straw for bedding','名词指小麦等谷物收割后留下的干燥茎秆。','The dry stems form a rough layer over the mud.','干茎在泥地上铺成一层粗糙覆盖物。'),C('straw.s2','drinks','He drank the iced tea through a paper straw rather than lifting the glass.','他用纸吸管喝冰茶，而不是拿起玻璃杯。','drink through a straw; paper/plastic straw','名词也指用来吸饮料的细管。','The tube carries liquid from the glass to his mouth.','细管把饮料从杯子输送到嘴里。')],M('She drank the iced tea through a straw by using a solid rod with no opening for liquid.','She drank through a hollow straw that carried tea from the glass.','没有中空通道的实心棒不能吸饮料。','meaning'),[Q(1,'What did the farmer spread over the path?','dry cereal stems','a paper drinking tube','a stone layer','Straw sense 1 is dried plant stalks.'),Q(2,'How did he drink the tea?','through a thin tube','through a bale of dry stems','from a sealed jar','A drinking straw lets liquid pass through it.'),Q(1,'Which phrase uses the farm sense?','a bale of straw for bedding','a paper straw in a glass','sip through a straw','The first refers to dry stems.'),Q(2,'Which material can be used to make a drinking straw?','paper','a whole bale of wheat stalks only','a stone stratum','Paper can form a hollow drinking tube.')]);
P('strawberry','Strawberry comes from Old English streawberige; the old compound is attested, though the original relationship of its first element to straw is uncertain.',C('strawberry.s1','food','We picked ripe strawberries from the low plants and froze half for winter.','我们从低矮的植株上摘下熟草莓，把一半冷冻起来留到冬天。','fresh/strawberry jam; a punnet of strawberries','名词指低矮植株结出的柔软红色水果。','The fruit is harvested ripe and can be eaten fresh or preserved.','这种水果成熟后采摘，可鲜食或保存。'),M('The basket contained strawberries, but every item was a hard green stone with no fruit flesh.','The basket contained ripe red fruit from strawberry plants.','只有坚硬果核而无果肉不是草莓水果。','meaning'),[Q(1,'What did they pick?','ripe red fruit','dry cereal stalks','a rare bacteria drug','A strawberry is the soft red fruit of a low plant.'),Q(1,'What did they do with half the harvest?','froze it for winter','used it as a stopper','planted it in the stratosphere','The example says half was frozen.'),Q(1,'Which phrase is natural?','strawberry jam','strawberry a jam','a jam of strawberrying','Strawberry commonly modifies jam.' ,'grammar'),Q(1,'Is the link between the old first element and modern straw certain?','no; the original connection is uncertain','yes, every berry grows in straw','yes, the word means a drinking tube','The entry avoids claiming an unsupported origin for the compound.')]);
P('stray','Stray came through Anglo-French estrayer, “wander away”; it is a verb, adjective, and noun for moving away, being lost, or an animal without its owner nearby.',[C('stray.s1','navigation','If you stray from the marked trail, return to the last sign rather than crossing the ravine.','如果你偏离标记路线，应返回最近的路标，不要穿过峡谷。','stray from a path/topic; stray into','动词指偏离正确路线、地点或话题。','The walker leaves the marked route.','行走者离开了标记路线。'),C('stray.s2','animals','A stray dog waited outside the shelter while staff looked for its owner.','一只走失的狗在收容所外等候，工作人员正在寻找它的主人。','a stray cat/dog; stray animal','形容词指离家走失的，或脱离主要群体的。','The dog is away from its home and owner.','狗离开了家和主人。'),C('stray.s3','animals','The shelter took in a stray that had been wandering near the station for days.','收容所收留了一只在车站附近游荡了好几天的走失动物。','take in a stray; feed a stray','名词指走失、附近没有主人的宠物。','The animal has wandered away and has no owner nearby.','这种动物走失，附近没有主人。')],M('The walker strayed from the trail by following every marker and staying exactly on the route.','The walker strayed from the trail by leaving the marked path.','沿着路标行走并保持在路线内不是偏离。','meaning'),[Q(1,'What should a hiker do after straying from the trail?','return to the last sign','continue deeper into the ravine','remove the trail markers','Stray from a route means leave it.'),Q(2,'What kind of dog waited outside the shelter?','one away from its home or owner','a trained guide dog with its handler','a stonemason’s pet at home','A stray animal has no owner nearby.'),Q(3,'What did the shelter take in?','a lost animal wandering near the station','a marked trail','a storehouse','As a noun, a stray is a pet that has wandered away.'),Q(2,'Which use makes stray an adjective?','a stray dog outside the shelter','to stray from the trail','feed a stray','The first phrase uses an adjective before dog.')]);
P('streak','Streak is recorded in Middle English for a line or mark, with deeper origin uncertain; it can mean a thin stripe, a run of repeated events or a quality, or moving very fast/marking with lines.',[C('streak.s1','appearance','A streak of red paint ran down the white door after the wet brush slipped.','湿刷子滑落后，一道红漆痕顺着白门流下。','a streak of color/dirt; leave a streak','名词指细长的颜色或污迹。','The paint forms a narrow line on the door.','油漆在门上形成细长痕迹。'),C('streak.s2','events','The club’s winning streak ended when it lost its first match in six weeks.','球队六周来首次输掉比赛，连胜纪录就此结束。','a winning/lucky streak; a streak of bad luck','名词也指同一结果连续发生的一段时期，或性格特征。','Repeated wins continue over several matches.','多场比赛中胜利连续出现。'),C('streak.s3','movement','A deer streaked across the road just before the headlights reached the bend.','车灯照到弯道前，一只鹿飞快地穿过了马路。','streak across/through; streak past','动词指高速移动，也可指留下一道细条纹。','The animal crosses rapidly in front of the car.','动物迅速从汽车前方穿过。')],M('The team’s winning streak ended after winning every game for a full year without a loss.','The team’s winning streak ended when it finally lost a match.','持续全胜没有结束连胜，输掉比赛才会终止纪录。','meaning'),[Q(1,'What appeared on the white door?','a narrow red line of paint','a broad blue panel','a streak of winnings','A streak can be a long thin mark.'),Q(2,'What ended for the club?','a period of consecutive wins','a storey count','a path away from the trail','A winning streak is a run of repeated wins.'),Q(3,'How did the deer move?','very quickly across the road','slowly behind the herd','straight into a strainer','Streak as a verb means move very fast.'),Q(2,'Which phrase uses streak for repeated events?','a six-game winning streak','a streak of red paint','the deer streaked across the road','The first names a period of successive wins.')]);
P('stream','Stream is from Old English strēam, a Germanic word for flowing water; it names a small river, a continuous flow, and the act of flowing or playing media as it arrives.',[C('stream.s1','geography','A narrow stream runs through the meadow and joins the larger river below the bridge.','一条狭窄的小溪流过草地，在桥下汇入较大的河流。','a mountain/forest stream; cross a stream','名词指一条小而窄的河流。','The watercourse joins the larger river.','这条水道汇入较大的河流。'),C('stream.s2','flow','A stream of visitors entered the gallery after the doors opened.','大门开放后，一波接一波的访客进入画廊。','a stream of people/information; steady stream','名词也指液体、人或事物连续不断的流动。','Visitors arrive continuously rather than in one group.','访客持续到来，而非一次性成群到达。'),C('stream.s3','media','We streamed the concert live to relatives who could not travel to the hall.','我们把音乐会实时在线播放给无法前往现场的亲友。','stream video/music online; live-stream','动词指边接收边通过互联网播放音视频，也可指流淌。','The audience watches the concert as the data arrives.','数据到达的同时，观众便能观看音乐会。')],M('The visitors entered as a stream, arriving continuously one after another, but the report says they all appeared in one single instant.','The visitors entered in a steady stream, arriving one after another after the doors opened.','连续不断的流动与所有人同一瞬间出现不相符。','meaning'),[Q(1,'What flowed through the meadow?','a small narrow river','a crowd entering the gallery','an online concert','Stream sense 1 is a small river.'),Q(2,'How did visitors arrive?','continuously, one after another','all at one instant','through an internet connection','A stream can be a continuous flow of people.'),Q(3,'What did the family do with the concert?','played it online as it arrived','stored it in a stoneware jar','walked away from the trail','Stream as a verb can play audio/video online in real time.'),Q(3,'Which sentence uses stream for flowing water?','A stream joined the river below the bridge.','A stream of visitors entered.','They streamed a concert.','The first names a small river.')]);
P('streambed','Streambed combines stream + bed and names the ground over which a stream flows, whether it is currently wet or seasonally dry.',C('streambed.s1','geography','After the dry season, the hikers followed the exposed streambed until they reached a pool.','旱季过后，徒步者沿着裸露的溪床走到一处水潭。','a dry/rocky streambed; follow a streambed','名词指小溪流经的地面或河床。','The channel remains even when little water is flowing.','即使水流很少，河道仍然存在。'),M('The hikers followed the streambed, but the route lay on a ridge far above and nowhere near the watercourse.','The hikers followed the channel where the stream normally flows.','远离水道的山脊不是溪床。','meaning'),[Q(1,'Where did the hikers walk?','along the ground where the stream normally flows','along a ridge far above it','inside a storehouse','A streambed is the ground beneath a stream.'),Q(1,'Was the streambed wet at that time?','no, it was exposed after the dry season','yes, it was a deep ocean strait','it was inside the pool','The source sense can be dry or wet.'),Q(1,'Which phrase is natural?','an exposed streambed','a streambed of a city bus','streambed the path to a pool','The adjective exposed describes the visible channel.'),Q(1,'What does bed mean in streambed?','the ground over which water flows','a sleeping place in a train','a layer of social rank','It names the channel floor.')]);
P('streamline','Streamline combines stream + line and first described a shape that lets air or water flow smoothly; as a verb it means simplify a process or give an object that shape.',[C('streamline.s1','efficiency','The office streamlined the permit process by combining three forms into one online application.','办公室把三张表合并为一份在线申请，精简了许可流程。','streamline a process/service; streamline operations','动词指删去不必要步骤，使流程更简单、更快。','Applicants now complete one form instead of three.','申请人现在填写一张表而不是三张。'),C('streamline.s2','design','Designers streamlined the kayak’s hull so water would pass around it with less drag.','设计师把皮艇船体改成流线型，使水流过时阻力更小。','streamline a body/hull; streamlined design','动词也指把物体塑造成让空气或水容易流过的形状。','The smooth hull reduces resistance in water.','平滑船体降低水中阻力。')],M('The office streamlined the process by adding six extra forms and requiring each to be submitted twice.','The office streamlined the process by combining forms and removing duplicate steps.','增加重复手续会使流程更繁琐，不是精简。','meaning'),[Q(1,'How did the office simplify permits?','combined three forms into one','added six more forms','sent applicants to a strait','Streamline a process means make it simpler and faster.'),Q(2,'Why reshape the kayak hull?','to reduce water resistance','to create more paperwork','to make the boat stop working','The second sense is shaping for smoother flow.'),Q(1,'Which phrase uses the efficiency sense?','streamline the application process','streamline a hull through water','a streamlined hull','The first refers to simplifying procedures.'),Q(2,'Which phrase uses the design sense?','streamline the kayak’s hull','streamline a permit system','streamline office paperwork','The hull is physically shaped to reduce drag.')]);
P('streamlined','Streamlined is the past participle of streamline; it describes a smooth, low-drag shape or an efficient process with wasteful steps removed.',[C('streamlined.s1','design','The streamlined train nose reduced air resistance at high speed.','流线型列车车头降低了高速行驶时的空气阻力。','a streamlined body/design; streamlined shape','形容词指形状平滑，便于空气或水流过。','The nose shape reduces drag as the train moves.','列车行驶时，车头形状减小阻力。'),C('streamlined.s1','operations','The clinic introduced a streamlined booking system that removed duplicate questions from the intake form.','诊所引入了一套精简的预约系统，删掉了登记表里重复的问题。','streamlined process/service; a streamlined system','形容词也表示流程经过简化、效率更高。','Removing repeated questions makes booking quicker.','删去重复问题使预约更快捷。')],M('The clinic called its booking system streamlined even though it added duplicate questions and several unnecessary steps.','The clinic’s streamlined system removed repeated questions and unnecessary steps.','增加重复问题和多余步骤会降低效率。','meaning'),[Q(1,'What did the train’s streamlined nose reduce?','air resistance','the number of ticket forms','the streambed depth','A streamlined shape lets air pass with less drag.'),Q(1,'What improved the clinic’s system?','removing duplicate questions','adding repeated questions','adding a second intake form','Streamlined can mean efficient and simplified.'),Q(1,'Which item is physically streamlined?','a smooth train nose','an efficient appointment process','a shortened application','The train nose has a low-drag shape.'),Q(1,'Which item is procedurally streamlined?','a booking process with unnecessary steps removed','a polished aerodynamic hull','a curved metal bracket','The first describes an efficient system.')]);
P('street','Street is from Old English strǣt, borrowed from Latin strata via “paved road”; it names a town road or, colloquially, ordinary people as opposed to experts or officials.',[C('street.s1','urban','The bookstore sits on a quiet street lined with houses and cafés.','书店位于一条安静的街道上，两旁是住宅和咖啡馆。','on a street; cross/walk down the street','名词指城镇中两侧有房屋或商店的道路。','The road passes between buildings in the town.','道路穿过城镇建筑之间。'),C('street.s2','public opinion','The policy sounded popular in the office, but people on the street were worried about rent.','这项政策在办公室里听起来很受欢迎，但普通民众担心房租。','on the street; street opinion','口语用法可指普通民众，与专家或官员相对。','The phrase contrasts everyday people with officials.','这个短语把普通人与官员对比。')],M('The bookstore is on a street even though there are no roads, houses, or shops anywhere nearby.','The bookstore is on a town road lined with houses and cafés.','没有道路或沿街建筑的地方不能称为这类城镇街道。','meaning'),[Q(1,'Where is the bookstore?','on a town road beside houses and cafés','inside a stratosphere','at the bottom of a stream','Street sense 1 is a road in a town.'),Q(2,'Who are “people on the street”?','ordinary members of the public','only traffic engineers','shop owners inside a storefront','The colloquial phrase means ordinary people.'),Q(1,'Which phrase uses the road sense?','walk down the street','ask people on the street','street opinion','The first names a physical town road.'),Q(2,'Which phrase uses the public sense?','people on the street worry about rent','the shop is on a street','cross the street safely','The first contrasts residents with officials.')]);
P('streetcar','Streetcar combines street + car and names an electric passenger vehicle that runs on rails set into a city street.',C('streetcar.s1','transport','The streetcar stopped at the corner to let passengers board before crossing downtown.','有轨电车在街角停下，让乘客上车后再穿过市中心。','ride/take a streetcar; streetcar line','名词指沿城市街道中的轨道行驶的电动客运车辆。','The vehicle follows rails embedded in the street.','车辆沿嵌在街道中的轨道行驶。'),M('The streetcar carried passengers along the city route on rubber tires with no rails beneath it.','The streetcar carried passengers along rails embedded in the city street.','没有轨道的轮胎汽车不是有轨电车。','distinction'),[Q(1,'Where did the streetcar stop?','at a city street corner','in a streambed','inside the storeroom','Streetcars run along urban rail routes.'),Q(1,'What guides its path?','rails set into the street','a paper storyline','a strap over its roof','A streetcar runs on rails.'),Q(1,'Which phrase is natural?','take the streetcar downtown','stow the streetcar in a bottle','streetcar the passenger quickly','One can take or ride a streetcar.' ,'collocation'),Q(1,'What does the compound combine?','street and car','straw and car','storey and car','It names a rail vehicle operating along city streets.')]);
P('strength','Strength is from Old English strengþu, a Germanic noun related to strong; it means physical power, influence, or the intensity of a quality or substance.',[C('strength.s1','fitness','After months of rehabilitation, the climber regained enough strength to carry a light pack.','经过数月康复，登山者恢复了足够体力，能背起轻便背包。','physical/core strength; build strength','名词指人或动物完成动作所需的身体力量。','The climber can lift and carry again.','登山者重新能够抬起并背负物品。'),C('strength.s2','influence','The union’s strength came from members who agreed to negotiate together.','工会的影响力来自同意共同谈判的成员。','political/economic strength; strength of a group','名词也指个人或群体影响他人和事件的能力。','Working together gives the union greater influence.','共同协作增强了工会的影响力。'),C('strength.s3','intensity','The chemist measured the strength of the solution before adding it to the sample.','化学家先测量溶液的浓度，再把它加到样本中。','strength of a solution/light/wind','名词也指感觉、物质、光线或风的强度。','The measurement determines how concentrated the liquid is.','测量可确定液体的浓度。')],M('After rehabilitation the climber regained strength, but remained unable to lift even a light pack.','After rehabilitation the climber regained enough physical power to carry a light pack.','恢复体力应能提升举物能力，而不应仍完全不能举起轻物。','meaning'),[Q(1,'What did the climber regain?','physical power to carry a pack','the union’s political influence','the solution’s concentration','Strength sense 1 is bodily power.'),Q(2,'Where did the union’s strength come from?','members negotiating together','a chemical solution','a strong wind','This sense means influence or power as a group.'),Q(3,'What did the chemist measure?','the concentration of the solution','the climber’s body mass','the streetcar’s speed','Strength can mean concentration or intensity.'),Q(2,'Which phrase uses strength for influence?','the strength of the union','the strength of her legs','the strength of the solution','The first refers to a group’s power to influence events.')]);
P('strengthen','Strengthen is strength + -en and means make something stronger or more effective, make an arrangement firmer, or build muscle through exercise.',[C('strengthen.s1','argument','The new evidence strengthened the case for replacing the unsafe bridge railing.','新证据强化了更换不安全桥栏的理由。','strengthen an argument/case/tie','及物动词指使某事更有力或更有效。','The evidence makes the recommendation more convincing.','证据让建议更有说服力。'),C('strengthen.s2','agreements','The two clinics strengthened their partnership by sharing equipment and staff training.','两家诊所通过共享设备和员工培训巩固了合作关系。','strengthen a partnership/tie; relations strengthen','动词也可指使安排更稳固，或关系自身更加稳固。','Shared resources make the partnership more stable.','资源共享让合作关系更加稳固。'),C('strengthen.s3','fitness','She strengthened her leg muscles with supervised exercises after the injury.','受伤后，她在监督下通过锻炼增强腿部肌肉。','strengthen muscles/back; exercises strengthen','动词指通过锻炼使肌肉更结实有力。','Repeated exercise improves muscle firmness and fitness.','反复锻炼让肌肉更结实、更有力。')],M('The new evidence strengthened the bridge case by making the safety argument less convincing and easier to dismiss.','The new evidence strengthened the case by making the safety argument more convincing.','增强论据应使其更有说服力，而非更容易被驳回。','meaning'),[Q(1,'What did the new evidence do?','made the safety case more convincing','made it easier to dismiss','repaired the railing by itself','Strengthen sense 1 means make an argument more effective.'),Q(2,'How did the clinics strengthen their partnership?','shared equipment and training','ended all cooperation','stopped working permanently','The second sense is making an arrangement more stable.'),Q(3,'What strengthened her leg muscles?','supervised exercises','a paper straw','a stocklist','Exercise can make muscles firmer and fitter.'),Q(1,'Which phrase uses strengthen for an argument?','strengthen the case for repairs','strengthen a muscle through exercise','strengthen a partnership','The first concerns a more convincing case.')]);
P('strenuous','Strenuous comes from Latin strenuus, “active or vigorous”; it describes activity needing much physical effort or an energetic, persistent attempt.',[C('strenuous.s1','exercise','The strenuous climb took four hours and left the hikers exhausted.','这段艰苦的攀登花了四小时，让徒步者筋疲力尽。','strenuous exercise/task; physically strenuous','形容词指需要大量体力的。','The long climb demands sustained physical effort.','长时间攀登需要持续体力。'),C('strenuous.s2','effort','The union made a strenuous effort to keep the factory open during negotiations.','谈判期间，工会全力争取让工厂继续运营。','a strenuous effort; strenuous opposition','形容词也指投入大量精力、积极全力以赴。','Members work hard to secure the outcome.','成员全力以赴争取结果。')],M('The strenuous climb required almost no effort and left every hiker completely fresh.','The strenuous climb demanded sustained effort and left the hikers exhausted.','不费力且毫不疲惫的行程不算 strenuous。','meaning'),[Q(1,'Why were the hikers exhausted?','the climb required sustained physical effort','the trail was flat and effortless','the union ended negotiations','Strenuous sense 1 means demanding much effort.'),Q(2,'What did the union do?','made a determined, energetic effort','gave up without trying','climbed a mountain','Sense 2 describes vigorous effort.'),Q(1,'Which activity is likely strenuous?','a steep four-hour climb','sitting quietly for five minutes','reading a short label','The climb calls for sustained physical exertion.'),Q(2,'Which phrase uses the effort sense?','a strenuous campaign to save the factory','a strenuous hill climb','a strenuous workout','The first emphasizes determined energetic action.')]);
P('strenuously','Strenuously is strenuous + -ly and means with intense physical or mental effort, or with forceful denial or opposition.',[C('strenuously.s1','effort','The crew worked strenuously to lift the fallen beam before the road reopened.','道路重新开放前，工人们奋力抬起倒下的横梁。','work/argue strenuously; strive strenuously','副词表示付出极大体力或脑力。','The heavy beam takes sustained effort to move.','移动这根沉重横梁需要持续用力。'),C('strenuously.s1','opposition','The manager strenuously denied changing the safety records.','经理极力否认自己改动过安全记录。','strenuously deny/object/oppose','副词也表示强烈、坚决地否认或反对。','The manager rejects the accusation forcefully.','经理强烈驳斥这项指控。')],M('The workers moved the heavy beam strenuously by lifting it with no effort or exertion.','The workers moved the beam strenuously, using intense effort to raise it.','毫不费力与 strenuously 的强力付出相反。','meaning'),[Q(1,'How did the crew lift the beam?','with intense effort','without any exertion','by using a paper straw','Strenuously means with great physical or mental effort.'),Q(1,'What did the manager do?','forcefully denied changing records','quietly admitted changing them','repaired the streetcar','The adverb can describe a strong denial.'),Q(1,'Which verb pairs naturally with strenuously?','strenuously oppose a proposal','strenuously a proposal of','strenuous oppose a proposal','The adverb modifies the verb oppose.' ,'grammar'),Q(1,'What is the adjective form?','strenuous','strength','stratum','Strenuously is formed from strenuous with -ly.' ,'word-formation')]);
P('streptomycin','Streptomycin is named from Streptomyces, the soil-bacteria genus that produces it, with -mycin used in names of antibiotics; it is used against certain bacterial infections.',C('streptomycin.s1','medicine','The physician prescribed streptomycin for the bacterial infection after checking the patient’s test results.','医生核对检测结果后，为这种细菌感染开了链霉素。','streptomycin treatment; prescribe streptomycin','名词指由土壤链霉菌产生、用于治疗某些细菌感染的抗生素。','The medicine is prescribed for a susceptible bacterial disease.','这种药用于治疗对其敏感的细菌性疾病。'),M('The physician prescribed streptomycin for a viral cold, claiming the antibiotic kills viruses.','The physician prescribed an appropriate treatment for the bacterial infection after reviewing the test results.','链霉素是抗生素，用于某些细菌感染，不是抗病毒药。','distinction'),[Q(1,'What kind of infection was treated?','a bacterial infection','a viral cold','a fungal rash only','Streptomycin is an antibiotic used against certain bacteria.'),Q(1,'What did the physician check first?','the patient’s test results','the storey count','the soup’s stock','The context states tests were reviewed before prescribing.'),Q(1,'Where is streptomycin produced?','by Streptomyces soil bacteria','by a streetcar engine','by a strawberry plant','The medicine’s name refers to the producing bacterial genus.' ,'word-formation'),Q(1,'Which statement is correct?','it is an antibiotic, not a treatment for viruses','it kills every virus','it is a cooking strainer','The example distinguishes bacterial from viral infections.')]);
})();
